"use strict";
const WORLDS=[{"slug":"w1","number":"01","name":"Blunder Hills","subtitle":"Fondations du compte","accent":"#8ecf72","goal":"Choisir tes classes, ouvrir les systèmes de base et vaincre Amarok.","gate":["Clé d’Amarok obtenue","100 % de précision sur Amarok","2–3 personnages créés","Stamps, Forge et Anvil actifs"],"steps":[{"id":"w1-character-create","phase":"CRÉATION","title":"Crée ton premier personnage avec The Fuzzy Dice","action":"Dans l’écran de création, choisis le Star Sign « The Fuzzy Dice » : ses 3 Talent Points donnent le meilleur départ général à un compte neuf. Le sexe et l’apparence n’influencent pas les statistiques. Si tu as déjà choisi « The Buff Guy », ne recommence pas ton compte : il reste correct pour le futur Warrior et les Star Signs pourront être changés plus tard.","why":"Star Sign et Star Talent sont deux systèmes différents : ici tu choisis le signe de naissance du personnage.","optional":false,"tag":"STAR SIGN RECOMMANDÉ","character":"Personnage 1 — futur Warrior","stats":["The Fuzzy Dice : +3 Talent Points et +3 LUK","Alternative acceptable : The Buff Guy"],"check":["Personnage créé","The Fuzzy Dice choisi, ou The Buff Guy conservé sans recommencer"]},{"id":"spawn","phase":"DÉPART","title":"Parle à Scripticus puis tue 5 Green Mushrooms","action":"À ton arrivée, ne touche pas encore au magasin ni au coffre. Clique sur Scripticus, accepte sa première quête, prends le portail à droite vers Spore Meadows, tue 5 Green Mushrooms, ramasse leurs objets puis retourne parler à Scripticus jusqu’à recevoir le Crimson String.","why":"C’est la première action réelle du compte et elle ouvre la suite du tutoriel.","optional":false,"tag":"QUÊTE 1","character":"Personnage 1 — futur Warrior","quest":"OBLIGATOIRE","check":["Quête acceptée avant de partir","5 Green Mushrooms tués","Retour effectué auprès de Scripticus","Crimson String obtenu"]},{"id":"gloves","phase":"DÉPART","title":"Craft les Boxing Gloves","action":"Ramasse du Cue Tape sur les Green Mushrooms, ouvre l’Anvil, fabrique les Boxing Gloves avec le Crimson String et le Cue Tape, puis équipe-les.","why":"Ton premier craft apprend la boucle monstre → recette → équipement.","optional":false,"tag":"CRAFT","gear":["Boxing Gloves équipés"],"skills":["Smithing : premier craft terminé"],"check":["Les gants sont équipés dans l’écran Equipment"]},{"id":"frogs","phase":"DÉPART","title":"Ouvre Froggy Fields","action":"Retourne sur la map Green Mushrooms, tue les monstres nécessaires au portail de droite, entre à Froggy Fields puis utilise Map Teleport comme demandé par Scripticus.","optional":false,"tag":"QUÊTE","quest":"OBLIGATOIRE","check":["Froggy Fields apparaît sur la carte","Inventory Bag A récupéré"]},{"id":"w1-auto","phase":"DÉPART","title":"Configure Auto et la barre d’attaques","action":"Place chaque attaque débloquée dans la barre, active Auto et vérifie que le personnage se déplace et utilise ses compétences. Une attaque apprise mais non équipée n’aide pas les gains AFK.","optional":false,"tag":"COMBAT","check":["Auto fonctionne","Attaques disponibles équipées"]},{"id":"talent5","phase":"TALENTS","title":"Dépense tes 5 premiers points","action":"Ouvre l’onglet Talents. Place les premiers points dans Sharpened Axe. Quand tu rates trop de coups, ajoute des points dans la statistique de précision de l’ennemi : WIS contre les premiers mobs pour ton futur Warrior.","why":"Au début, les dégâts de Sharpened Axe accélèrent davantage que les petits bonus défensifs.","optional":false,"tag":"BUILD","character":"Personnage 1 — futur Warrior","talents":["Sharpened Axe : 5 points d’abord","Ensuite Gilded Sword pour les dégâts","WIS uniquement si ta précision passe sous 100 %"],"stats":["Précision : 100 % sur la map actuelle","Survie AFK : 100 % avec nourriture"],"check":["5 points dépensés","Mini Material Pouch obtenu auprès de Scripticus"]},{"id":"w1-storage","phase":"DÉPART","title":"Utilise seulement le coffre gratuit","action":"Dépose les matériaux inutiles pour l’objectif actuel et garde l’arme, la nourriture et les objets de quête sur ton personnage. N’achète encore aucun coffre : tes premières pièces doivent servir à la nourriture et au Forge Fuel.","optional":false,"tag":"INVENTAIRE","check":["Matériaux déposés","Aucun coffre acheté trop tôt","Emplacements libres pour le push"]},{"id":"w1-free-route","phase":"DÉPART","title":"Garde une route entièrement gratuite","action":"N’achète aucun Gem Pack, bundle, compagnon ou accélération. Toutes les étapes du guide utilisent uniquement les systèmes gratuits et les monnaies gagnées en jouant. Ferme toute offre et reprends la quête de Scripticus.","why":"Aucun achat en argent réel n’est nécessaire pour atteindre les mondes et l’endgame.","optional":false,"tag":"0 €","check":["Aucune dépense réelle","Route gratuite comprise"]},{"id":"w1-afkinfo","phase":"DÉPART","title":"Lis l’écran AFK avant chaque nouvelle map","action":"Contrôle Accuracy, Survivability et Kills/hr. Corrige d’abord la précision vers 100 %, puis la survie avec nourriture, puis les dégâts.","optional":false,"tag":"RÈGLE","stats":["Accuracy : 100 %","Survivability : 100 %","Kills/hr en hausse après amélioration"],"check":["Trois valeurs repérées"]},{"id":"w1-cards","phase":"DÉPART","title":"Equipe tes premières Monster Cards","action":"Ouvre le menu Cards, équipe les cartes donnant précision, dégâts ou AFK gain et complète le set accessible. Remplace-les quand une nouvelle map apporte mieux.","optional":false,"tag":"ÉQUIPEMENT","check":["Slots de cards remplis","Bonus utile sélectionné"]},{"id":"w1-first-money","phase":"ARGENT","title":"Constitue ta première réserve de pièces","action":"Reste sur Green Mushrooms, ou Froggy Fields si tu y tues plus vite, et laisse Auto combattre jusqu’à posséder assez de pièces pour une pile de nourriture ET le premier Forge Fuel affiché au magasin. Les monstres donnent directement des pièces : ne vends pas Cue Tape, Frog Legs, ores, logs ni objets de quête.","why":"Cette étape finance les deux achats indispensables sans sacrifier les matériaux des prochains crafts.","optional":false,"tag":"FARM COURT","stats":["Accuracy : 100 % sur la map choisie","Survivability : 100 % si tu pars AFK"],"check":["Prix de la nourriture lu au magasin","Prix du Forge Fuel lu","Total des deux prix atteint","Matériaux conservés"]},{"id":"food","phase":"DÉPART","title":"Achète uniquement la nourriture nécessaire","action":"Avec la réserve de l’étape précédente, achète au magasin une seule pile de nourriture adaptée, équipe-la dans un Food Slot puis vérifie AFK Info. N’achète une deuxième pile que si la première ne permet pas 100 % de survie.","optional":false,"tag":"ACHAT 1","gear":["1 pile de nourriture équipée"],"stats":["Survie AFK : 100 %"],"check":["Prix vérifié avant achat","Nourriture visible dans un Food Slot","Survie contrôlée"]},{"id":"hat","phase":"VILLE","title":"Récupère le casque gratuit","action":"Près du portail W2 en ville, écris exactement « give me hat » dans le chat et équipe le Real Civil Engineer Helmet.","why":"Un bonus immédiat sans farm.","optional":false},{"id":"anvil","phase":"VILLE","title":"Lance Thread à l’Anvil","action":"Active l’Anvil, sélectionne Thread comme production et dépense tes premiers points Anvil dans Speed. Répète cette action dès que tu crées un personnage.","why":"Un personnage qui ne produit rien perd de l’XP Smithing en permanence.","optional":false,"tag":"MÉTIER","skills":["Smithing : produire Thread","Anvil Points : Speed en premier, puis Capacity si tu capes pendant l’AFK"],"check":["Thread est en production","La jauge de production avance"]},{"id":"forge","phase":"VILLE","title":"Achète le fuel puis lance la Forge","action":"Utilise le reste de ta première réserve pour acheter le Forge Fuel affiché au magasin. Place ensuite Copper Ore + fuel dans un seul slot et attends seulement les Copper Bars nécessaires au Pickaxe et à l’arme suivante. Si l’argent manque, retourne farmer Green Mushrooms ou Froggy Fields jusqu’au prix exact manquant.","optional":false,"tag":"ACHAT 2","skills":["Mining : Copper Ore requis","Smithing : préparer les premiers crafts"],"check":["Forge Fuel acheté","Minerai + fuel placés","Copper Bars récupérés"]},{"id":"pickaxe","phase":"MÉTIERS","title":"Craft le Copper Pickaxe","action":"Va à la mine de cuivre avec ton futur Warrior, monte Mining jusqu’au niveau requis, fabrique le Copper Pickaxe et équipe-le sur le personnage qui mine.","why":"Les outils ont leur propre puissance et leurs propres Upgrade Stones.","optional":false,"tag":"MINING","character":"Personnage 1 — futur Warrior","talents":["Preset métier plus tard : Brute Efficiency puis Idle Skilling","Ne sacrifie pas le build combat de ton pusher avant d’avoir 2 presets"],"skills":["Mining : niveau 5 minimum","Copper Ore : assez pour Pickaxe + arme"],"gear":["Copper Pickaxe"],"check":["Copper Pickaxe équipé","Efficacité suffisante pour miner Copper à 100 %"]},{"id":"chopper","phase":"MÉTIERS","title":"Prépare le métier Chopping","action":"Garde les logs ramassés et, dès la création du Mage, équipe-lui une hache. Le Mage deviendra ton spécialiste Chopping ; le Warrior ne doit couper que le strict nécessaire.","optional":false,"tag":"CHOPPING","character":"Personnage 2 — futur Mage","talents":["Book of the Wise pour WIS","Smart Efficiency puis Active AFK'er sur le preset métier"],"skills":["Chopping : viser niveau 5–10 au début"],"check":["Les logs nécessaires aux crafts immédiats sont en coffre"]},{"id":"glumlee","phase":"MINING","title":"Fais la chaîne de Glumlee","action":"Dans la zone minière, accepte les quêtes de Glumlee, mine le Copper demandé et récupère les récompenses/outils. Garde les ores et bars nécessaires au prochain Pickaxe.","optional":false,"tag":"QUÊTE IMPORTANTE","character":"Warrior","quest":"IMPORTANTE","check":["Quêtes minières initiales validées","Copper stocké"]},{"id":"mining-eff","phase":"MINING","title":"Atteins 100 % efficacité sur Copper","action":"Equipe Pickaxe, cards et talents Mining disponibles. Si l’efficacité est faible, monte Brute Efficiency/STR plutôt que de rester plus longtemps avec un mauvais rendement.","optional":false,"tag":"PALIER","character":"Warrior","stats":["Mining efficiency : 100 % sur Copper"],"check":["100 % affiché","Meilleur outil équipé"]},{"id":"woodsman","phase":"CHOPPING","title":"Fais la chaîne du Woodsman","action":"Avec le Mage, parle au Woodsman, coupe les logs demandés et valide les quêtes donnant accès aux recettes/récompenses utiles.","optional":false,"tag":"QUÊTE IMPORTANTE","character":"Mage","quest":"IMPORTANTE","check":["Quêtes Chopping initiales validées","Logs stockés"]},{"id":"chop-eff","phase":"CHOPPING","title":"Atteins 100 % efficacité sur Oak Logs","action":"Equipe la meilleure hache accessible, WIS et talents d’efficacité. Coupe uniquement assez pour les crafts et quêtes avant de reprendre le leveling combat.","optional":false,"tag":"PALIER","character":"Mage","stats":["Chopping efficiency : 100 % sur l’arbre cible"],"check":["100 % affiché","Matériaux immédiats obtenus"]},{"id":"w1-frogs","phase":"PUSH MAP PAR MAP","title":"Termine Froggy Fields proprement","action":"Ouvre le portail suivant, ramasse les Frog Legs nécessaires aux crafts et prends les quêtes présentes sans interrompre longtemps la route principale.","optional":false,"tag":"MAP","check":["Portail terminé","Frog Legs stockées","NPC contrôlés"]},{"id":"beans","phase":"PUSH","title":"Atteins Valley of the Beans","action":"Traverse Green Mushrooms → Froggy Fields → Bored Beans. Sur chaque map, reste jusqu’à ce que le compteur du portail atteigne zéro. Au niveau 10, parle à Promotheus.","why":"Promotheus attribue ta classe de base.","optional":false,"tag":"PORTAIL","character":"Personnage 1 — Beginner","stats":["Précision : 100 % sur Bored Beans"],"check":["Niveau 10 atteint","Dialogue de Promotheus disponible"]},{"id":"class1","phase":"CLASSES","title":"Personnage 1 : choisis Warrior","action":"Chez Promotheus, choisis Warrior. Ce personnage sera ton premier pusher et ton spécialiste Mining, puis prendra la branche Squire/Dark Knight.","why":"Warrior facilite les minerais requis par les premiers équipements.","optional":false,"tag":"CHOIX PERMANENT","character":"Personnage 1 — Warrior → Squire → Dark Knight","talents":["Tab 1 combat : Sharpened Axe → Gilded Sword → Meat Shank","Tab Warrior : Carry a Big Stick → Absolute Unit","WIS seulement pour corriger la précision"],"stats":["Stat principale dégâts : STR","Stat de précision en W1 : WIS","Précision : toujours 100 %"],"check":["Classe Warrior confirmée","Preset combat sauvegardé"]},{"id":"w1-beans","phase":"PUSH MAP PAR MAP","title":"Termine Valley of the Beans","action":"Choisis ta classe chez Promotheus, termine le portail principal et garde le portail Orion séparé pour plus tard si 1 500 kills prennent trop longtemps.","optional":false,"tag":"MAP","check":["Classe obtenue","Portail principal terminé","Orion fait ou reporté explicitement"]},{"id":"w1-tree","phase":"PUSH MAP PAR MAP","title":"Traverse les zones forestières","action":"Pousse les mobs forestiers dans l’ordre affiché par les portails. A chaque map, vérifie précision/survie et conserve les matériaux de la prochaine arme.","optional":false,"tag":"MAPS","check":["Première zone forestière terminée","Matériaux d’arme conservés"]},{"id":"w1-carrot","phase":"PUSH MAP PAR MAP","title":"Traverse les Carrotmen","action":"Equipe nourriture avant l’AFK, termine le compteur et garde les drops pour quests/crafts. Ne farm pas une carte rare avant d’avoir ouvert le boss.","optional":false,"tag":"MAP","check":["Carrotmen terminés","Survie 100 %"]},{"id":"w1-glublin","phase":"PUSH MAP PAR MAP","title":"Traverse les Glublins et Wode Boards","action":"Monte Accuracy via stat secondaire, Target Stamp ou cards si elle baisse. Termine les deux portails avant de revenir optimiser les métiers.","optional":false,"tag":"MAPS","check":["Glublins terminés","Wode Boards terminés","100 % précision"]},{"id":"w1-boas","phase":"PUSH MAP PAR MAP","title":"Traverse Gigafrogs et Walking Sticks","action":"Compare arme et talents si les kills/heure chutent. Utilise les matériaux accumulés pour l’amélioration qui accélère réellement le portail.","optional":false,"tag":"MAPS","check":["Gigafrogs terminés","Walking Sticks terminés","Kills/heure contrôlés"]},{"id":"w1-villa","phase":"PUSH MAP PAR MAP","title":"Atteins Encroaching Forest Villas","action":"Ouvre la map précédant Amarok, parle aux NPC concernés par les clés et libère assez d’inventaire pour les objets de quête/boss.","optional":false,"tag":"MAP","check":["Forest Villas accessible","NPC de clé repéré","Inventaire libéré"]},{"id":"char2","phase":"CLASSES","title":"Crée le personnage 2 avec The Book Worm","action":"Quand le deuxième slot s’ouvre, crée le personnage destiné à devenir Mage et choisis « The Book Worm » pour WIS et Class EXP. Rejoue ensuite les quêtes courtes de Scripticus, lance Thread à l’Anvil et pousse-le jusqu’au niveau 10.","optional":false,"tag":"STAR SIGN","character":"Personnage 2 — futur Mage","stats":["Star Sign : The Book Worm"],"check":["The Book Worm choisi","Personnage 2 créé","Thread en production","Niveau 10 atteint"]},{"id":"class2","phase":"CLASSES","title":"Personnage 2 : choisis Mage","action":"Chez Promotheus, choisis Mage. Il devient ton spécialiste Chopping et prendra plus tard Wizard/Elemental Sorcerer.","optional":false,"tag":"CHOIX PERMANENT","character":"Personnage 2 — Mage → Wizard → Elemental Sorcerer","talents":["Tab 1 : Sharpened Axe puis Gilded Sword","Tab Mage : Power Overwhelming → Knowledge is Power","AGI si la précision manque"],"stats":["Stat principale dégâts : WIS","Stat de précision : AGI","Précision : 100 %"],"skills":["Chopping : niveau 10 puis seulement selon les crafts"],"check":["Classe Mage confirmée","Hache équipée"]},{"id":"char3","phase":"CLASSES","title":"Crée le personnage 3 avec Flexo Bendo","action":"Dès que le troisième slot s’ouvre, crée le futur Archer et choisis « Flexo Bendo » pour AGI et Movement Speed. Active l’Anvil, équipe la nourriture puis pousse-le jusqu’à Promotheus.","optional":false,"tag":"STAR SIGN","character":"Personnage 3 — futur Archer","stats":["Star Sign : Flexo Bendo"],"check":["Flexo Bendo choisi","Personnage 3 créé","Thread en production","Niveau 10 atteint"]},{"id":"class3","phase":"CLASSES","title":"Personnage 3 : choisis Archer","action":"Choisis Archer. Il prendra Bowman/Siege Breaker et deviendra le spécialiste Catching à partir du W2.","optional":false,"tag":"CHOIX PERMANENT","character":"Personnage 3 — Archer → Bowman → Siege Breaker","talents":["Tab 1 : Sharpened Axe puis Gilded Sword","Tab Archer : High Polymer Limbs → Have Another!","STR si la précision manque"],"stats":["Stat principale dégâts : AGI","Stat de précision : STR","Précision : 100 %"],"check":["Classe Archer confirmée","Arc ou arme actuelle équipé"]},{"id":"rosterplan","phase":"CLASSES","title":"Note l’ordre des personnages suivants","action":"Ne crée pas plusieurs Beginners secrets. Après Warrior, Mage, Archer, couvre en W2 les six branches : Squire, Barbarian, Wizard, Shaman, Bowman, Hunter. Réserve le personnage 7 au Journeyman/Maestro/Voidwalker.","why":"Les choix de subclasses sont difficiles à corriger ; ce plan évite un compte déséquilibré.","optional":false,"tag":"À CONSERVER","check":["Plan du roster compris avant de choisir une subclass"]},{"id":"skills","phase":"MÉTIERS","title":"Monte Mining et Chopping juste assez","action":"Envoie le Warrior au Copper/Grandioso Canyon et le Mage aux arbres. Vise seulement l’efficacité nécessaire aux crafts de tes armes et outils suivants.","why":"Ne bloque pas plusieurs jours sur les métiers avant W2 : l’Alchemy accélérera tout.","optional":false},{"id":"stamps","phase":"COMPTE","title":"Débloque les Stamps sans rien acheter","action":"Fais uniquement la quête de Mr Pigibank et dépose les stamps déjà gagnés. Ouvre ensuite le magasin, note séparément le prix de Target, Shield et Mana Stamp, mais ne les achète pas encore.","why":"Séparer le déblocage du système, le farm et l’achat évite de te retrouver sans nourriture.","optional":false,"tag":"QUÊTE IMPORTANTE","quest":"IMPORTANTE","check":["Menu Stamps ouvert","Stamps gratuits déposés","Prix des trois stamps notés"]},{"id":"vault","phase":"COMPTE","title":"Active le Vault","action":"Termine la quête W1 qui ouvre le Vault, puis consulte ses objectifs. Valide les objectifs gratuits sans retarder le push.","why":"Le Vault donne des bonus permanents account-wide.","optional":false,"tag":"SYSTÈME","quest":"IMPORTANTE","check":["Interface Vault accessible","Premiers bonus réclamés"]},{"id":"picnic","phase":"QUÊTES IMPORTANTES","title":"Fais Picnic Stowaway progressivement","action":"Accepte sa chaîne et valide les demandes réalisables pendant le push. Reporte une étape longue, mais conserve les quest items au coffre.","optional":false,"tag":"QUÊTE","quest":"IMPORTANTE","check":["Chaîne commencée","Quest items conservés","Etape longue faite ou reportée"]},{"id":"dogbone","phase":"QUÊTES IMPORTANTES","title":"Fais la chaîne de Dog Bone","action":"Dans Forest Villas, termine ses demandes pour obtenir les clés/récompenses liées à Amarok et le Star Talent important de la chaîne.","optional":false,"tag":"CLÉS","quest":"OBLIGATOIRE","check":["Quêtes Dog Bone avancées","Clé disponible","Star Talent/récompense récupéré si atteint"]},{"id":"w1-stamp-money","phase":"ARGENT","title":"Farm les pièces des stamps","action":"Additionne les prix affichés de Target, Shield et Mana Stamp, puis ajoute le prix d’une pile de nourriture de réserve. Farm sur la map la plus avancée où tu conserves 100 % de précision et de survie jusqu’à atteindre ce total. Les pièces tombent automatiquement : garde tous les matériaux.","optional":false,"tag":"FARM CIBLÉ","check":["Total exact calculé","Map rentable choisie","100 % précision et survie","Somme atteinte sans vendre les matériaux"]},{"id":"pig-stamps-shop","phase":"COMPTE","title":"Achète puis dépose les trois stamps","action":"Retourne au magasin seulement après le farm précédent. Achète Target, Shield et Mana Stamp, dépose-les immédiatement chez Mr Pigibank, puis monte d’abord Target si ta précision est inférieure à 100 %. Arrête les niveaux dès que le prochain coût entame ta réserve de nourriture.","optional":false,"tag":"ACHAT 3","check":["Target Stamp déposé","Shield Stamp déposé","Mana Stamp déposé","Réserve de nourriture conservée"]},{"id":"w1-capacity","phase":"INVENTAIRE","title":"Améliore les bags du pusher","action":"Craft ou récupère les Material/Food Bags accessibles afin que le personnage ne cesse pas l’AFK avec un inventaire plein. Equipe les bags, ne les laisse pas stockés.","optional":false,"tag":"QUALITÉ DE VIE","check":["Material Bag équipé","Food Bag équipé","Capacité suffisante pour l’AFK prévu"]},{"id":"w1-stone-money","phase":"ARGENT","title":"Finance uniquement les pierres utiles","action":"Choisis d’abord l’arme et l’outil que tu garderas jusqu’à Amarok, compte leurs slots libres, puis lis le prix des Upgrade Stones W1. Farm sur ta meilleure map jusqu’au coût exact des pierres nécessaires + une pile de nourriture. N’achète aucune pierre pour un équipement que tu vas remplacer immédiatement.","optional":false,"tag":"FARM CIBLÉ","check":["Équipements durables choisis","Slots comptés","Prix total atteint","Réserve de nourriture intacte"]},{"id":"w1-stones","phase":"ÉQUIPEMENT","title":"Achète et applique les Upgrade Stones","action":"Achète seulement le nombre de pierres calculé à l’étape précédente. Applique-les d’abord à l’arme du pusher, puis à son outil principal. Arrête dès que les slots utiles sont remplis.","optional":false,"tag":"ACHAT 4","check":["Arme améliorée","Outil principal amélioré","Aucune pierre gaspillée"]},{"id":"w1-weapon","phase":"ÉQUIPEMENT","title":"Craft la meilleure arme rentable avant Amarok","action":"Ouvre l’Anvil, épingle la recette, rassemble uniquement les matériaux manquants et craft l’arme. Ne retarde pas le boss pour une arme disproportionnellement chère.","optional":false,"tag":"CRAFT","character":"Pusher","check":["Recette épinglée","Arme craftée et équipée","Upgrade Stones appliquées"]},{"id":"w1-statue-money","phase":"ARGENT","title":"Prépare l’argent des Statues","action":"Au niveau 22, ouvre le magasin et additionne le prix affiché du Statue Man et du Sculpting Tool. Garde en plus le coût d’une pile de nourriture. Farm la map la plus avancée avec 100 % précision/survie jusqu’à atteindre ce total ; ne vends aucune statue ni matériau de craft.","optional":false,"tag":"FARM CIBLÉ","check":["Deux prix relevés","Réserve nourriture ajoutée","Somme totale atteinte"]},{"id":"statues","phase":"COMPTE","title":"Achète et débloque les Statues","action":"Achète maintenant le Statue Man, installe-le, prends sa quête puis achète le Sculpting Tool avec la somme préparée. Dépose toutes tes statues sur un seul personnage pour l’instant.","why":"Éparpiller les statues ralentit les premiers niveaux.","optional":false,"tag":"ACHAT 5","quest":"IMPORTANTE","check":["Statue Man installé en ville","Sculpting Tool acheté","Statues déposées sur un seul personnage"]},{"id":"tasks28","phase":"COMPTE","title":"Débloque Tasks au niveau 28","action":"Au niveau 28, active Tasks/Achievements en ville et commence les objectifs W1 réalisables sans gros détour.","optional":false,"tag":"SYSTÈME","check":["Menu Tasks accessible","Premiers merits non dépensés au hasard"]},{"id":"w1-star","phase":"TALENTS","title":"Dépense les Star Talent points utiles","action":"Equipe les talents star obtenus par quêtes/achievements uniquement s’ils servent le push ou le métier actuel. Garde des points si le prochain unlock est meilleur.","optional":false,"tag":"BUILD","check":["Star Talents inspectés","Aucun point dépensé dans un bonus inutile par défaut"]},{"id":"owl","phase":"OPTIONNEL","title":"Lance Orion l’Owl","action":"Dans Feather Forest, active le mini-système et prends quelques upgrades faciles. Reviens plus tard pour les MegaFeathers.","why":"Très bon boost initial, mais ne retarde pas Amarok.","optional":true,"tag":"OPTIONNEL"},{"id":"gear","phase":"ÉQUIPEMENT","title":"Prépare Amarok","action":"Craft une arme actuelle, équipe nourriture + potions de dégâts/précision, et utilise les cartes de précision. Copper/Iron suffit si tes stats sont correctes.","why":"L’arme et la précision comptent plus qu’un set complet coûteux.","optional":false},{"id":"key","phase":"BOSS","title":"Obtiens la clé d’Amarok","action":"Termine la ligne de Scripticus jusqu’à la clé, entre à Encroaching Forest Villas puis ouvre la porte du boss.","why":"Garde ensuite la quête quotidienne de clé active.","optional":false},{"id":"amarok-check","phase":"BOSS","title":"Valide les statistiques avant Amarok","action":"Ouvre AFK Info sur Forest Villas, vise 100 % précision et survie, équipe nourriture/potions/cards et libère de l’inventaire.","optional":false,"tag":"VALIDATION","stats":["Accuracy : 100 %","Survivability : 100 %"],"gear":["Arme actuelle","Nourriture","Cards précision/dégâts"],"check":["Clé","Inventaire libre","Barre d’attaques"]},{"id":"amarok-mechanics","phase":"BOSS","title":"Apprends les trois menaces d’Amarok","action":"Reste à distance correcte du poing, évite l’attaque pulsante et détruis le healing totem dès son apparition. Reviens améliorer les dégâts si le soin annule ton progrès.","optional":false,"tag":"MÉCANIQUES","check":["Poing évité","Pulse reconnu","Healing Totem détruit"]},{"id":"amarok","phase":"BOSS","title":"Bats Amarok Normal","action":"Reste en bas, évite le poing pulsant et détruis rapidement le totem de soin. Récupère le Glacier Quartz et la recette du set.","why":"La victoire ouvre Yum-Yum Desert.","optional":false},{"id":"set","phase":"APRÈS BOSS","title":"Craft 2–3 sets Amarok","action":"Priorise torse, jambes et bottes ; utilise un casque Gold ou meilleur. Fais circuler les sets entre tes personnages.","why":"Amarok reste rentable jusque vers W4 ; les casques demandent trop de ressources tôt.","optional":false},{"id":"tasks","phase":"OPTIONNEL","title":"Prends les Merits W1 utiles","action":"Dans Tasks, vise Hemoglobin puis les bonus de boss/production. Garde les tickets de Colosseum au lieu de les brûler.","why":"Hemoglobin soigne à chaque kill et sécurise le push.","optional":true,"tag":"IMPORTANT"},{"id":"w1-merits","phase":"APRÈS BOSS","title":"Dépense les Merits W1 dans l’ordre utile","action":"Priorise Hemoglobin pour la survie au kill, puis les bonus qui accélèrent boss, production ou progression. Garde des points si le prochain rang apporte davantage.","optional":false,"tag":"MERITS","check":["Hemoglobin débloqué/monté","Merits restants non gaspillés"]},{"id":"w1-exit","phase":"PASSAGE W2","title":"Fais le contrôle de sortie W1","action":"Avant de te concentrer sur W2, vérifie trois classes de base, Anvil active sur tous, Forge alimentée, Stamps/Statues/Vault ouverts, clé quotidienne et nourriture.","optional":false,"tag":"VALIDATION FINALE","check":["Warrior, Mage, Archer","Anvil sur tous","Forge active","Stamps","Statues","Vault","Clé Amarok","Nourriture"]}]},{"slug":"w2","number":"02","name":"Yum-Yum Desert","subtitle":"Alchemy et subclasses","accent":"#edbd61","goal":"Débloquer l’Alchemy, les subclasses, les dungeons et battre Efaunt.","gate":["Six subclasses couvertes","Alchemy lancée chaque jour","Shaquracy/FMJ démarrées","Efaunt Normal vaincu"],"steps":[{"id":"enter-w2","phase":"ARRIVÉE","title":"Entre dans Yum-Yum Grotto","action":"Après Amarok, utilise le portail W2 de Blunder Hills. Parle une fois à chaque NPC de la ville et ouvre le magasin, l’Arcade et le portail de gauche.","optional":false,"tag":"DÉCOUVERTE","character":"Personnage 1 — Warrior pusher","check":["Yum-Yum Grotto débloquée sur la carte","Tous les NPC de ville ont été visités"]},{"id":"w2-first-money","phase":"ARGENT","title":"Finance ton premier achat W2","action":"Lis d’abord le prix du BobJoePickle, de la nourriture W2 et du coffre de stockage le moins cher. Retourne sur ta meilleure map W1, ou farm le premier monstre W2 seulement avec 100 % précision/survie, jusqu’à posséder le prix du pickle + nourriture + coffre. Ne vends aucun matériau W2.","optional":false,"tag":"FARM CIBLÉ","check":["Trois prix relevés","Map sûre choisie","Somme atteinte","Matériaux conservés"]},{"id":"w2-shop","phase":"ARRIVÉE","title":"Achète les permanents W2 dans le bon ordre","action":"Achète d’abord 1 BobJoePickle et place-le au coffre, puis une pile de nourriture W2 si elle améliore ta survie, puis le coffre de stockage le moins cher. Reporte les autres bags et coffres : refais un farm ciblé avant chaque achat au lieu de vider tes pièces.","why":"Le pickle devient un prérequis tardif et ne peut pas être rattrapé instantanément.","optional":false,"tag":"ACHAT","check":["Premier BobJoePickle stocké","Nourriture achetée seulement si utile","Premier coffre acheté","Réserve de combat conservée"]},{"id":"w2-daily-budget","phase":"ARGENT","title":"Sépare le budget quotidien W2","action":"Au début de chaque session, réserve d’abord le prix du BobJoePickle et d’une recharge de nourriture. Le reste seulement peut servir aux bags, stamps, outils et crafts. Si la réserve n’est pas complète, farm avant d’ouvrir les autres magasins.","optional":false,"tag":"BUDGET","check":["Pickle réservé","Nourriture réservée","Reste disponible identifié"]},{"id":"w2-food-check","phase":"PUSH","title":"Teste la nourriture avant chaque nouvelle famille de mobs","action":"Entre sur la nouvelle map, ouvre AFK Info et vérifie Survivability. Si elle est sous 100 %, équipe la nourriture déjà achetée ; si elle ne suffit pas, relève le prix du palier suivant et farm uniquement la différence sur la dernière map sûre.","optional":false,"tag":"SURVIE","check":["Nouvelle map testée","Survie 100 %","Aucun achat inutile"]},{"id":"arcade","phase":"ARRIVÉE","title":"Active l’Arcade","action":"Parle au NPC de l’Arcade, récupère les balls disponibles et dépense les premiers points sur des bonus permanents utiles. Ne dépense pas de gems pour accélérer ce système.","optional":false,"tag":"COMPTE","check":["Arcade accessible","Premier bonus permanent acheté"]},{"id":"kazam-1","phase":"ALCHEMY","title":"Commence la quête de Kazam","action":"Parle à Kazam en ville et termine ses demandes jusqu’à l’ouverture de l’interface Alchemy. Change de personnage une fois l’interface ouverte pour vérifier qu’elle est account-wide.","optional":false,"tag":"QUÊTE OBLIGATOIRE","quest":"OBLIGATOIRE","check":["Bouton Alchemy accessible","Les quatre cauldrons colorés sont visibles"]},{"id":"cauldron-assign","phase":"ALCHEMY","title":"Assigne tous les personnages aux cauldrons","action":"Place chaque personnage disponible dans un cauldron. Mets le futur Shaman sur la couleur qui bloque ta prochaine bubble et ne laisse aucun slot gratuit inutilisé.","optional":false,"tag":"INSTALLATION","character":"Tout le roster","check":["Chaque personnage est assigné","Aucun cauldron utile n’est inactif"]},{"id":"cauldron-spend","phase":"ALCHEMY","title":"Dépense les points de cauldron","action":"Dans chaque couleur, alterne Speed et Luck pour accélérer les tentatives de nouvelles bubbles ; monte Capacity seulement si la jauge cape souvent pendant ton absence.","why":"Une grande capacité vide ne produit rien de plus.","optional":false,"tag":"PRIORITÉ","check":["Speed améliorée dans les couleurs actives","Luck améliorée","Prochaine tentative de bubble lancée"]},{"id":"bubble-first","phase":"ALCHEMY","title":"Débloque les bubbles de métiers","action":"Cherche Hearty Diggy en orange, Hocus Choppus en violet et Sanic Tools en vert. Monte-les avec les matériaux faciles plutôt que d’attendre un niveau parfait.","optional":false,"tag":"BUBBLES","skills":["Mining : Hearty Diggy","Chopping : Hocus Choppus","Catching et outils : Sanic Tools"],"check":["Au moins une bubble de métier débloquée","Matériaux nécessaires notés ou imprimés plus tard"]},{"id":"accuracy-bubbles","phase":"ALCHEMY","title":"Atteins Shaquracy et FMJ","action":"Continue les découvertes jusqu’à Shaquracy pour la précision et FMJ pour la défense. Dès qu’elles apparaissent, monte-les en priorité lorsque le push perd 100 % précision ou survie.","optional":false,"tag":"BUBBLES CLÉS","stats":["Précision : Shaquracy","Défense : FMJ"],"check":["Shaquracy découverte ou cauldron activement poussé vers elle","FMJ découverte ou cauldron activement poussé vers elle"]},{"id":"vial-daily","phase":"ALCHEMY","title":"Fais tes tentatives de Vials","action":"Dans l’onglet Vials, dépose au sol un exemplaire du matériau demandé, puis répète avec les ressources faciles. Fais les tentatives quotidiennes avant que le compteur ne soit perdu.","optional":false,"tag":"QUOTIDIEN","check":["Tentatives du jour utilisées","Nouveaux vials faciles montés vers le niveau 4"]},{"id":"char4","phase":"ROSTER","title":"Crée le personnage 4 : deuxième Warrior","action":"Dès que le slot est ouvert, crée un Warrior, refais Scripticus, lance Thread à l’Anvil et pousse-le jusqu’à Speccius. Il prendra Barbarian.","optional":false,"tag":"PERSONNAGE","character":"Personnage 4 — Warrior → Barbarian → Blood Berserker","talents":["Même build Warrior combat que le personnage 1","Preset métier futur : Fishing"],"check":["Personnage 4 Warrior","Thread en production","Niveau 40 et Speccius atteint"]},{"id":"char5","phase":"ROSTER","title":"Crée le personnage 5 : deuxième Archer","action":"Crée un Archer, active immédiatement l’Anvil et pousse-le jusqu’à Speccius. Il prendra Hunter pour préparer Trapping W3.","optional":false,"tag":"PERSONNAGE","character":"Personnage 5 — Archer → Hunter → Beast Master","talents":["Build Archer combat","Preset métier futur : Trapping"],"check":["Personnage 5 Archer","Anvil active","Speccius atteint"]},{"id":"char6","phase":"ROSTER","title":"Crée le personnage 6 : deuxième Mage","action":"Crée un Mage, équipe nourriture et attaques, puis pousse-le jusqu’à Speccius. Il prendra Shaman et sera assigné à Alchemy.","optional":false,"tag":"PERSONNAGE","character":"Personnage 6 — Mage → Shaman → Bubonic Conjuror","talents":["Build Mage combat","Bubble Breakthrough après la subclass"],"check":["Personnage 6 Mage","Speccius atteint","Assigné à un cauldron"]},{"id":"spec-squire","phase":"SUBCLASSES","title":"Personnage 1 : choisis Squire","action":"À The Mimic Hole, termine la quête de Speccius et choisis Squire. Garde ce personnage comme pusher et futur spécialiste Construction/DK.","optional":false,"tag":"CHOIX PERMANENT","character":"P1 — Squire","check":["Squire confirmé","Talents Squire examinés","Preset combat conservé"]},{"id":"spec-wizard","phase":"SUBCLASSES","title":"Personnage 2 : choisis Wizard","action":"Conduis ton Mage jusqu’à Speccius et choisis Wizard. Il préparera Worship puis Elemental Sorcerer.","optional":false,"tag":"CHOIX PERMANENT","character":"P2 — Wizard","check":["Wizard confirmé","Preset Chopping séparé"]},{"id":"spec-bowman","phase":"SUBCLASSES","title":"Personnage 3 : choisis Bowman","action":"Conduis ton Archer jusqu’à Speccius et choisis Bowman. Il devient le spécialiste Catching et futur Siege Breaker.","optional":false,"tag":"CHOIX PERMANENT","character":"P3 — Bowman","check":["Bowman confirmé","Preset Catching créé"]},{"id":"spec-barb","phase":"SUBCLASSES","title":"Personnage 4 : choisis Barbarian","action":"Choisis Barbarian. Monte Monster Decimator pour les portails, mais reporte le long grind Apocalypse Zow tant que W3 n’est pas ouvert.","optional":false,"tag":"CHOIX PERMANENT","character":"P4 — Barbarian","talents":["1 point dans les attaques","Monster Decimator","Apocalypse Zow seulement quand 100k kills/map devient rapide"],"check":["Barbarian confirmé","Preset Fishing créé"]},{"id":"spec-hunter","phase":"SUBCLASSES","title":"Personnage 5 : choisis Hunter","action":"Choisis Hunter. Il servira au combat actif W3, à Trapping et plus tard à Breeding.","optional":false,"tag":"CHOIX PERMANENT","character":"P5 — Hunter","talents":["Attaques Hunter pour l’AFK","Looty Mc Shooty seulement selon les objets découverts"],"check":["Hunter confirmé"]},{"id":"spec-shaman","phase":"SUBCLASSES","title":"Personnage 6 : choisis Shaman","action":"Choisis Shaman, remets-le dans Alchemy et investis d’abord dans Bubble Breakthrough et Earlier Education sur le preset dédié.","optional":false,"tag":"CHOIX PERMANENT","character":"P6 — Shaman","talents":["Bubble Breakthrough","Earlier Education","Sharing Some Smarts"],"check":["Shaman confirmé","Assigné au cauldron prioritaire"]},{"id":"push-mimics","phase":"PUSH MAP PAR MAP","title":"Nettoie The Mimic Hole","action":"Avec ton pusher, maintiens 100 % précision, tue les Mimics jusqu’à l’ouverture du portail et termine Speccius avant de quitter définitivement la map.","optional":false,"tag":"MAP","character":"Squire pusher","stats":["Précision : 100 %","Survie AFK : 100 %"],"check":["Portail suivant ouvert","Subclass du pusher obtenue"]},{"id":"push-pots","phase":"PUSH MAP PAR MAP","title":"Traverse les Sandy Pots","action":"Equipe nourriture et la meilleure arme réaliste. Tue jusqu’à ce que le compteur du portail affiché en jeu atteigne zéro ; récupère les Glass Shards sans bloquer le push pour leur rareté.","optional":false,"tag":"MAP","check":["Portail Sandy Pots terminé","Drops placés dans le coffre"]},{"id":"push-steaks","phase":"PUSH MAP PAR MAP","title":"Traverse les Mashed Potatoes et Tysons","action":"Fais chaque map dans l’ordre, vérifie l’écran AFK après chaque changement et remonte Shaquracy/FMJ si précision ou survie passent sous 100 %.","optional":false,"tag":"MAPS","stats":["100 % précision sur la map actuelle","100 % survie avec nourriture"],"check":["Portail Mashed Potatoes ouvert","Portail Tysons ouvert"]},{"id":"push-moons","phase":"PUSH MAP PAR MAP","title":"Atteins les Moonmoons","action":"Continue jusqu’aux Moonmoons, équipe les attaques sur la barre et compare les kills/heure plutôt que le seul chiffre de dégâts.","optional":false,"tag":"MAP","check":["Moonmoons accessibles","Attaques du pusher sur la barre","Kills/heure contrôlés"]},{"id":"w2-gear-list","phase":"ÉQUIPEMENT","title":"Liste les composants avant de crafter","action":"Épingle l’arme et les pièces réellement nécessaires pour Efaunt, puis note chaque matériau manquant. Affecte Fishing, Catching et combat à ces composants un par un ; ne craft pas un set complet si précision et survie sont déjà à 100 %.","optional":false,"tag":"PRÉPARATION","check":["Recettes épinglées","Matériaux manquants listés","Personnages affectés","Craft minimum choisi"]},{"id":"w2-gear-coins","phase":"ARGENT","title":"Finance le craft et les pierres W2","action":"Lis le prix des pierres et consommables nécessaires à l’équipement choisi. Farm la meilleure map W2 avec 100 % précision/survie jusqu’au total, puis achète uniquement la quantité correspondant aux slots libres.","optional":false,"tag":"FARM CIBLÉ","check":["Slots comptés","Prix total calculé","Somme atteinte","Pierres appliquées"]},{"id":"fishing-open","phase":"MÉTIERS","title":"Débloque et commence Fishing","action":"Envoie le Barbarian sur les premiers poissons, équipe une Fishing Rod et utilise le preset Fishing. Monte uniquement jusqu’aux poissons requis pour Anvil Tab 2, quêtes et équipement immédiat.","optional":false,"tag":"FISHING","character":"P4 — Barbarian","skills":["Fishing : efficacité avant XP","Stocker les poissons requis, puis retourner au push"],"check":["Fishing Rod équipée","Premier poisson obtenu","Preset Fishing actif pendant le claim"]},{"id":"catching-open","phase":"MÉTIERS","title":"Débloque et commence Catching","action":"Envoie le Bowman sur les premiers insectes, équipe le meilleur Net accessible et utilise Elusive Efficiency, AGI et les talents Catching.","optional":false,"tag":"CATCHING","character":"P3 — Bowman","skills":["Catching : 100 % efficacité sur la cible accessible","Smithing continue en parallèle"],"check":["Net équipé","Premier insecte obtenu","Preset Catching actif"]},{"id":"anvil-tab2","phase":"CRAFT","title":"Débloque Anvil Tab 2","action":"Dans Tasks W2, complète les objectifs requis pour la recette, puis rassemble poissons, insectes, minerais et matériaux monstres. N’essaie pas de fabriquer tout l’onglet : cible armes et outils.","optional":false,"tag":"ÉQUIPEMENT","check":["Recette Anvil Tab 2 débloquée ou progression identifiée","Prochaine arme du pusher épinglée","Prochain outil de chaque spécialiste épinglé"]},{"id":"efaunt-keys","phase":"BOSS","title":"Débloque les clés d’Efaunt","action":"Suis la quête principale de Cowbo Jones jusqu’à obtenir l’accès au boss. Termine d’abord les demandes obligatoires et laisse les quêtes d’XP sans système pour plus tard.","optional":false,"tag":"QUÊTE OBLIGATOIRE","quest":"OBLIGATOIRE","check":["Clé d’Efaunt obtenue","Efaunt’s Tomb accessible"]},{"id":"w2-boss-reserve","phase":"BOSS","title":"Prépare une réserve avant Efaunt","action":"Garde une clé, une pile complète de nourriture et assez d’espace d’inventaire avant la tentative. N’utilise pas les dernières pièces dans un stamp ou une pierre juste avant le boss.","optional":false,"tag":"VALIDATION","check":["Clé disponible","Nourriture complète","Inventaire libre","Réserve de pièces conservée"]},{"id":"efaunt-check","phase":"BOSS","title":"Fais le contrôle avant Efaunt","action":"Ouvre l’écran AFK sur la dernière map : vise 100 % précision et survie. Mets ta meilleure arme, nourriture, potions de précision/dégâts et attaques sur la barre.","optional":false,"tag":"VALIDATION","character":"Squire ou meilleur pusher","gear":["Meilleure arme disponible","Nourriture de soin","Potions utiles","Amarok armor suffisante si bien améliorée"],"check":["100 % précision","100 % survie","Clé disponible","Inventaire avec de la place"]},{"id":"skills","phase":"MÉTIERS","title":"Débloque Fishing et Catching","action":"Utilise Barbarian pour Fishing et Bowman pour Catching. Vise les matériaux exacts de l’Anvil Tab 2 et de tes armes, puis retourne push.","why":"Les spécialistes gagnent beaucoup plus d’efficacité avec leurs talents.","optional":false},{"id":"post","phase":"COMPTE","title":"Commence Post Office","action":"Termine la ligne de Postboy Pablob jusqu’aux commandes. Fais les livraisons bon marché et dirige les boxes selon le métier du personnage.","why":"Le reset au Silver Pen évite de laisser grimper les coûts trop haut.","optional":false},{"id":"dungeon","phase":"HEBDO","title":"Fais le Party Dungeon","action":"Pendant Happy Hour, utilise Find Party au Grandfrog’s Backyard. Dépense Flurbos sur Rex Rings puis Serrated Rex Rings.","why":"Les anneaux restent excellents pour le skilling et les stats dungeon sont permanentes.","optional":false},{"id":"kilroy","phase":"HEBDO","title":"Débloque Kilroy","action":"Fais sa quête en ville puis effectue les deux maps chaque semaine. Achète surtout les upgrades permanentes.","why":"Kilroy est un flux hebdomadaire à ne pas laisser dormir.","optional":false},{"id":"gear","phase":"ÉQUIPEMENT","title":"Prépare Efaunt","action":"Mets à jour l’arme de ton pusher, monte Shaquracy jusqu’à 100 % de précision et équipe de la nourriture. Amarok armor suffit généralement.","why":"N’attends pas un set parfait : précision et dégâts décident du combat.","optional":false},{"id":"efaunt","phase":"BOSS","title":"Bats Efaunt Normal","action":"Détruis d’abord le bras en haut à droite, puis le bras-pistolet. Termine les autres bras et frappe la tête quand elle devient vulnérable.","why":"Le drop ouvre Frostbite Tundra.","optional":false},{"id":"talent-traps","phase":"VÉRIFICATION","title":"Évite les talents pièges","action":"Laisse Mocking Shout à 1, évite No Pain No Gain tôt et Crazy Concoctions dans l’auto-rotation.","why":"Ces talents peuvent soigner les mobs, réduire ta survie ou casser l’automatisation.","optional":false}]},{"slug":"w3","number":"03","name":"Frostbite Tundra","subtitle":"Automation du compte","accent":"#84cce5","goal":"Mettre en route Construction, Printer, Refinery, Trapping et Worship avant Chizoar.","gate":["3D Printer construit","Refinery alimentée en continu","Traps posés sur tous","Chizoar Normal vaincu"],"steps":[{"id":"w3-enter","phase":"ARRIVÉE","title":"Entre à Frostbite Towndra sans acheter","action":"Utilise le portail après Efaunt, parle à Hoggindaz et ouvre Construction. Visite le magasin uniquement pour relever les prix des coffres, bags, outils, Trapping Boxes et skulls ; n’achète encore rien.","optional":false,"tag":"DÉCOUVERTE","check":["Construction ouverte","Prix W3 relevés","Aucune dépense prématurée"]},{"id":"w3-money","phase":"ARGENT","title":"Finance l’installation du Monde 3","action":"Additionne le prix de la nourriture W3, d’une Trapping Box et d’un skull pour chaque personnage actif, puis ajoute uniquement le coffre ou bag qui évite un cap immédiat. Farm ta meilleure map W2 ou Efaunt si rentable jusqu’à ce total. Garde les matériaux de Construction, Refinery et crafts.","optional":false,"tag":"FARM CIBLÉ","check":["Budget nourriture calculé","Boxes et skulls budgétés","Une amélioration de capacité justifiée","Somme atteinte sans vendre les matériaux"]},{"id":"w3-shopping","phase":"ARRIVÉE","title":"Achète l’installation W3 dans l’ordre","action":"Achète d’abord nourriture, Trapping Boxes et skulls pour les personnages disponibles. Achète ensuite un seul coffre ou bag si nécessaire, puis les outils uniquement au moment où leur recette ou efficacité devient utile. Retourne farmer avant chaque dépense supplémentaire.","optional":false,"tag":"ACHAT","check":["Nourriture équipée","Boxes équipées","Skulls équipés","Achat de capacité justifié"]},{"id":"w3-cog-plan","phase":"CONSTRUCTION","title":"Construis d’abord un plateau d’EXP joueurs","action":"Place tes meilleurs cogs Player EXP autour des personnages qui construisent, compare l’EXP/heure avant et après, puis fabrique les cogs suivants. Ne recherche le Build Rate massif qu’après avoir monté les niveaux des constructeurs.","optional":false,"tag":"UNE PRIORITÉ","check":["Plateau avant comparé","Player EXP privilégiée","Prochain cog lancé"]},{"id":"w3-hog-1","phase":"QUÊTE PRINCIPALE","title":"Termine l’introduction de Hoggindaz","action":"Suis les dialogues et crafts demandés dans l’ordre. Ne quitte pas la chaîne tant que Construction, Cogs, Refinery, Shrines et 3D Printer ne sont pas présentés.","optional":false,"tag":"OBLIGATOIRE","quest":"OBLIGATOIRE","check":["Construction Table accessible","Cog Board accessible","Refinery accessible"]},{"id":"cog-players","phase":"CONSTRUCTION","title":"Place tes constructeurs sur le Cog Board","action":"Place d’abord les deux Squires/DK disponibles sur le board. Génère des cogs, équipe ceux avec Player EXP et remplace régulièrement les cogs faibles.","why":"Le niveau Construction des personnages débloque leurs meilleurs bonus de Build Rate.","optional":false,"tag":"INSTALLATION","character":"Tous les Squires/DK","check":["Constructeurs placés","Tous les emplacements disponibles contiennent un cog ou personnage","Player EXP privilégiée"]},{"id":"cog-claim","phase":"CONSTRUCTION","title":"Installe la routine des cogs","action":"Réclame les nouveaux cogs avant que les emplacements de génération soient pleins. Compare Player EXP, Build Rate et flags ; recycle les cogs manifestement inférieurs.","optional":false,"tag":"ROUTINE","check":["Génération non capée","Cogs faibles remplacés","Flags orientés vers les constructeurs"]},{"id":"build-priority-1","phase":"CONSTRUCTION","title":"Mets le 3D Printer en tête de file","action":"Dans la file de bâtiments, priorise le 3D Printer devant les bonus confort. Utilise les premières ressources W3 uniquement sur les prérequis directs.","optional":false,"tag":"PRIORITÉ","check":["3D Printer en construction","Matériaux manquants identifiés"]},{"id":"ref-red","phase":"REFINERY","title":"Démarre Redox Salt","action":"Ajoute le fuel demandé au sel rouge et désactive l’arrêt involontaire. Vérifie le temps de fuel ; si un matériau manque, prépare son impression dès que le Printer est construit.","optional":false,"tag":"TIME-GATE","check":["Redox Salt produit","Fuel Time positif","Prochain rank surveillé"]},{"id":"ref-green","phase":"REFINERY","title":"Démarre Explosive Salt sans affamer le rouge","action":"N’active le sel suivant que lorsque le rouge produit assez pour l’alimenter. Garde les sels de base en avance sur toutes les couches supérieures.","optional":false,"tag":"TIME-GATE","check":["Production rouge reste positive","Explosive Salt alimenté","Aucune couche haute ne vide la couche basse"]},{"id":"w3-refinery-reserve","phase":"REFINERY","title":"Sécurise le fuel avant un rank-up","action":"Ouvre les coûts par cycle du sel ciblé, vérifie que les drops ou le 3D Printer couvrent la consommation, puis constitue plusieurs cycles de réserve. Ne monte le rank qu’une fois le débit inférieur durablement positif.","optional":false,"tag":"VALIDATION","check":["Coût par cycle lu","Production comparée","Réserve constituée","Rank-up autorisé ou reporté"]},{"id":"printer-unlock","phase":"3D PRINTER","title":"Réclame le talent Sampling","action":"Une fois le Printer construit, récupère le talent star Sampling sur chaque personnage. Monte-le avec les points disponibles et équipe-le avant chaque échantillon.","optional":false,"tag":"OBLIGATOIRE","character":"Tout le roster","talents":["Printer Sampling équipé","Sample Rate progressivement vers 90 %"],"check":["Talent obtenu sur chaque personnage utilisé","Printer accessible depuis la ville"]},{"id":"sample-mining","phase":"3D PRINTER","title":"Prends les samples de Mining","action":"Equipe le preset Mining, meilleur Pickaxe, cards, nourriture et talents d’efficacité du Squire. Va sur le minerai réellement nécessaire au fuel/craft puis prends le sample.","optional":false,"tag":"SAMPLE","character":"Squire/DK","skills":["Copper/Iron ou minerai de fuel prioritaire","Sample Rate le plus élevé disponible"],"check":["Preset Mining actif au moment du sample","Ore assigné dans le Printer"]},{"id":"sample-chop","phase":"3D PRINTER","title":"Prends les samples de Chopping","action":"Equipe le Wizard/ES en Chopping avec la meilleure hache, WIS, efficacité et AFK gain. Sample les logs nécessaires à Refinery, Alchemy et Construction.","optional":false,"tag":"SAMPLE","character":"Wizard/ES","check":["Preset Chopping actif","Logs assignés au Printer"]},{"id":"sample-fish","phase":"3D PRINTER","title":"Prends les samples de Fishing","action":"Equipe le Barbarian/BB avec rod, STR, efficacité et talents Fishing. Prends le poisson qui bloque le prochain craft ou fuel.","optional":false,"tag":"SAMPLE","character":"Barbarian/BB","check":["Preset Fishing actif","Poisson assigné au Printer"]},{"id":"sample-catch","phase":"3D PRINTER","title":"Prends les samples de Catching","action":"Equipe le Bowman/SB avec Net, AGI et talents Catching. Sample l’insecte consommé par le prochain objectif plutôt que le plus haut par réflexe.","optional":false,"tag":"SAMPLE","character":"Bowman/SB","check":["Preset Catching actif","Insecte assigné au Printer"]},{"id":"w3-sample-session","phase":"3D PRINTER","title":"Prépare chaque sample séparément","action":"Sur le spécialiste concerné, équipe preset métier, outil, cards, nourriture et talents d’efficacité ; vérifie le taux de sample, capture une seule ressource puis compare-la à l’ancien sample avant de l’écraser. Recommence métier par métier.","optional":false,"tag":"SESSION","check":["Preset correct","Équipement correct","Taux vérifié","Nouveau sample comparé"]},{"id":"printer-slots","phase":"3D PRINTER","title":"Affecte chaque slot à un besoin précis","action":"Réserve d’abord les slots aux fuels de Refinery et matériaux de bâtiments. Les ressources d’Alchemy et d’équipement viennent seulement lorsque tous les time-gates tournent.","optional":false,"tag":"PRIORITÉ","check":["Tous les slots disponibles utilisés","Fuels prioritaires imprimés","Aucun slot sur une ressource sans objectif"]},{"id":"trap-quest","phase":"TRAPPING","title":"Fais la quête Lord of the Hunt","action":"Suis Lord of the Hunt jusqu’à obtenir l’accès aux critters et à la première Trapping Box. Attrape le critter demandé avant de passer au suivant.","optional":false,"tag":"QUÊTE IMPORTANTE","quest":"IMPORTANTE","check":["Trapping débloqué","Premier critter capturé"]},{"id":"trap-everyone","phase":"TRAPPING","title":"Equipe une Trapping Box sur chaque personnage","action":"Achète ou craft une box pour chacun, équipe-la, déplace chaque personnage sur la map du critter et pose tous ses traps disponibles.","optional":false,"tag":"TOUS LES PERSONNAGES","character":"Tout le roster","check":["Une box équipée sur chacun","Aucun personnage avec un trap disponible inutilisé"]},{"id":"trap-duration","phase":"TRAPPING","title":"Choisis la durée selon ton rythme","action":"Utilise une durée courte seulement si tu peux réellement réclamer à temps. Pour la nuit ou une journée, choisis un trap long afin de ne pas laisser les emplacements terminés plusieurs heures.","optional":false,"tag":"ROUTINE","check":["Durée adaptée à la prochaine connexion","Critter correspondant au prochain bâtiment sélectionné"]},{"id":"eagle-eye","phase":"TRAPPING","title":"Utilise Eagle Eye sans oublier les niveaux individuels","action":"Sur le Hunter, monte Eagle Eye pour centraliser les claims. Vérifie néanmoins que tous gagnent leur propre XP Trapping et améliorent leurs boxes.","optional":false,"tag":"HUNTER","character":"Hunter/Beast Master","talents":["Eagle Eye","Reflective Eyesight ensuite"],"check":["Claim global effectué","Niveaux Trapping individuels contrôlés"]},{"id":"worship-open","phase":"WORSHIP","title":"Débloque Goblin Gorefest","action":"Equipe un skull sur le personnage qui lance le Tower Defence, construis les premières towers et termine assez de vagues pour obtenir les souls nécessaires.","optional":false,"tag":"TOWER DEFENCE","character":"Hunter conseillé pour le contrôle","check":["Goblin Gorefest accessible","Premier record sauvegardé","Premières souls obtenues"]},{"id":"worship-all","phase":"WORSHIP","title":"Worship avec chaque personnage","action":"Equipe un skull sur tous les personnages et dépense leur charge individuellement. N’utilise pas Charge Syphon comme remplacement permanent des niveaux personnels.","optional":false,"tag":"TOUS LES PERSONNAGES","character":"Tout le roster","check":["Skull équipé sur chacun","Aucune charge proche du cap","Chaque personnage possède de l’XP Worship"]},{"id":"w3-skull-materials","phase":"WORSHIP","title":"Craft les skulls sans bloquer le push","action":"Épingle la recette du prochain skull, liste souls et matériaux manquants, puis Worship avec chaque personnage jusqu’au total. Craft un skull à la fois et équipe-le immédiatement avant de préparer le suivant.","optional":false,"tag":"CRAFT","check":["Recette épinglée","Matériaux réunis","Un skull crafté","Skull équipé"]},{"id":"tower-upgrades","phase":"CONSTRUCTION","title":"Améliore les towers avant de refaire le TD","action":"Monte les niveaux des towers de dégâts et contrôle avec Construction, puis seulement relance un TD. Ne répète pas une run identique sans nouveau multiplicateur.","optional":false,"tag":"TOWER DEFENCE","check":["Towers améliorées","Nouveau record tenté après amélioration"]},{"id":"library-build","phase":"CONSTRUCTION","title":"Construis la Talent Book Library","action":"Place la Library tôt dans la file après les bâtiments structurants. Dès qu’un checkout est prêt, prends un livre utile au pusher ou spécialiste plutôt que de laisser la charge caper.","optional":false,"tag":"BÂTIMENT CLÉ","check":["Library construite","Premier livre réclamé","Prochain checkout en recharge"]},{"id":"library-books","phase":"TALENTS","title":"Réserve les livres aux talents structurants","action":"Priorise les talents de dégâts/respawn du pusher, Bubble Breakthrough/Tenteyecle, efficacité des spécialistes et talents account-wide. Remplace les mauvais rolls progressivement.","optional":false,"tag":"PRIORITÉ","check":["Talent du pusher booké","Talent métier principal booké","Aucun checkout capé"]},{"id":"deathnote-build","phase":"CONSTRUCTION","title":"Construis Death Note","action":"Débloque Death Note puis consulte les kills W1/W2. Ne farm pas immédiatement toutes les skulls : vise d’abord les matériaux de craft et maps faciles.","optional":false,"tag":"MULTIKILL","check":["Death Note accessible","Premier objectif de kills choisi"]},{"id":"shrines-place","phase":"SHRINES","title":"Regroupe tes personnages sous les Shrines","action":"Place les Shrines sur une map où plusieurs personnages doivent gagner niveaux et portails. Evite de les déplacer juste avant leur niveau suivant.","optional":false,"tag":"ACCOUNT-WIDE","check":["Shrines posées sur une map active","Plusieurs personnages en bénéficient"]},{"id":"w3-map-1","phase":"PUSH MAP PAR MAP","title":"Traverse Sheepies et Frost Flakes","action":"Avec le pusher, équipe les attaques, nourriture et précision. Termine chaque compteur de portail dans l’ordre et récupère les matériaux nécessaires aux premiers crafts W3.","optional":false,"tag":"MAPS","stats":["100 % précision","100 % survie AFK"],"check":["Sheepies terminés","Frost Flakes terminés"]},{"id":"w3-map-2","phase":"PUSH MAP PAR MAP","title":"Traverse Sir Staches et Bloques","action":"Contrôle Shaquracy/FMJ à chaque nouvelle map. Si les kills/heure chutent, améliore arme, bubbles, stamps et foods avant de farm un set complet.","optional":false,"tag":"MAPS","check":["Sir Staches terminés","Bloques terminés","Kills/heure comparés"]},{"id":"w3-map-3","phase":"PUSH MAP PAR MAP","title":"Atteins les Mamooths et Snowmans","action":"Continue les portails avec le personnage qui obtient le meilleur résultat AFK. Laisse les autres monter leurs niveaux de classe sur les maps déjà ouvertes.","optional":false,"tag":"MAPS","check":["Mamooths accessibles","Snowmans accessibles","Autres personnages placés avec un objectif"]},{"id":"chizoar-keyline","phase":"BOSS","title":"Termine la ligne de clé Chizoar","action":"Fais les quêtes obligatoires menant à la clé et conserve les matériaux demandés. Vérifie que l’entrée du boss est disponible avant de consommer tes ressources d’équipement.","optional":false,"tag":"QUÊTE OBLIGATOIRE","quest":"OBLIGATOIRE","check":["Clé Chizoar obtenue","Entrée du boss accessible"]},{"id":"chizoar-check","phase":"BOSS","title":"Valide le build avant Chizoar","action":"Equipe meilleure arme, nourriture, potions, cards boss/précision et attaques. Vise 100 % précision ; garde assez de dégâts pour détruire les orbes de soin rapidement.","optional":false,"tag":"VALIDATION","gear":["Arme W3 ou meilleure accessible","Nourriture de soin","Cards précision/boss","Inventaire libre"],"check":["100 % précision","Survie suffisante","Orbes tuées rapidement sur l’essai"]},{"id":"worship","phase":"WORSHIP","title":"Dépense la charge avant le cap","action":"Fais le Tower Defense avec Hunter, puis worship avec chaque personnage plutôt que siphonner toute la charge.","why":"La charge capée est du temps perdu et les niveaux de métier sont individuels.","optional":false},{"id":"starsigns","phase":"COMPTE","title":"Débloque le Telescope","action":"Fais la quête du Telescope et complète les constellations accessibles. Rush Chronus puis Hydron pour 2 puis 3 signes équipés.","why":"Les Star Signs sont désormais account-wide.","optional":false},{"id":"postoffice","phase":"QUOTIDIEN","title":"Continue le Post Office","action":"Fais les commandes raisonnables, reset avec Silver Pen si le coût explose et spécialise les boxes par personnage.","why":"C’est une source durable d’efficacité et de dégâts.","optional":false},{"id":"chizoar","phase":"BOSS","title":"Bats Chizoar Normal","action":"Monte l’arme, prends nourriture/précision, détruis les orbes pendant le spin et évite les attaques Sword Slash et Whirl.","why":"Le Glacier Quartz ouvre Hyperion Nebula.","optional":false},{"id":"arm","phase":"CONSTRUCTION","title":"Programme Automation Arm","action":"Après le boss, construis ses niveaux utiles : nourriture depuis le coffre, collecte et automatisations quotidiennes.","why":"Réduit énormément la microgestion du compte.","optional":false}]},{"slug":"w4","number":"04","name":"Hyperion Nebula","subtitle":"Elite classes et account multipliers","accent":"#d392dd","goal":"Obtenir toutes les Elite Classes et faire tourner Lab, Breeding et Cooking.","gate":["6 Elite Classes obtenues","Killer Brightside branché","Breeding/Cooking actifs","Troll Normal vaincu"],"steps":[{"id":"w4-enter","phase":"ARRIVÉE","title":"Entre dans Hyperion Nebula","action":"Après Chizoar, active le portail W4, parle aux NPC de la ville et visite Laboratory, Breeding et Cooking avant de pousser la première map.","optional":false,"tag":"DÉCOUVERTE","check":["Ville W4 débloquée","Trois skills W4 ouverts","Magasin contrôlé"]},{"id":"lab-upload","phase":"LABORATORY","title":"Upload les personnages non-pushers","action":"Garde ton meilleur pusher dehors et place les autres dans les tubes du Lab. Commence avec une ligne simple vers les premiers nodes plutôt qu’un réseau esthétique.","optional":false,"tag":"INSTALLATION","character":"Tout le roster sauf pusher","check":["Pusher hors du Lab","Tous les autres gagnent de l’XP Lab","Premier node connecté"]},{"id":"lab-line","phase":"LABORATORY","title":"Réduis les espaces morts du réseau","action":"Déplace les personnages dans les tubes pour que leurs lignes se touchent au minimum nécessaire. Réorganise après chaque niveau de line width ou retrait d’un personnage.","optional":false,"tag":"RÉSEAU","check":["Aucune grosse zone de ligne inutilisée","Tous les nodes visés restent actifs"]},{"id":"w4-lab-one-node","phase":"LABORATORY","title":"Branche un seul bonus supplémentaire","action":"Choisis le prochain node qui accélère réellement le push, déplace un personnage à la fois et vérifie que les anciens nodes restent connectés. Arrête dès que le nouveau bonus s’allume ; ne réorganise pas toute la ligne sans objectif.","optional":false,"tag":"ANTI-DISPERSION","check":["Node cible choisi","Anciennes connexions conservées","Nouveau node actif"]},{"id":"lab-bonuses","phase":"LABORATORY","title":"Cible les nodes qui accélèrent le compte","action":"Branche d’abord les nodes donnant impression, kills de portail, Alchemy et bonus globaux accessibles. Ignore temporairement un node marginal s’il exige plusieurs personnages supplémentaires.","optional":false,"tag":"PRIORITÉ","check":["Bonus Printer accessible branché","Killer Brightside identifié","Coût en personnages de chaque node contrôlé"]},{"id":"lab-brightside","phase":"LABORATORY","title":"Branche Killer Brightside avant le gros push","action":"Monte Lab et line width jusqu’à connecter Killer Brightside. Vérifie son activation juste avant chaque session de portails W4.","why":"Ce node double les kills comptés pour les portails.","optional":false,"tag":"NODE CLÉ","check":["Killer Brightside allumé","Pusher toujours hors du Lab"]},{"id":"lab-chips","phase":"LABORATORY","title":"Débloque les slots de chips","action":"Monte le niveau Lab individuel des personnages jusqu’aux paliers de slots. Equipe les chips disponibles selon leur rôle et ne laisse aucun slot ouvert sans raison.","optional":false,"tag":"ÉQUIPEMENT","check":["Slots débloqués contrôlés sur chaque personnage","Chips équipées sur les personnages actifs"]},{"id":"w4-rotation-budget","phase":"CHIPS / JEWELS","title":"Prépare le coût avant la rotation","action":"Ouvre le Chip Shop, note la ressource exacte et la quantité de chaque chip/jewel prioritaire, puis affecte Cooking, Breeding, 3D Printer ou farm de mobs à une seule ressource manquante à la fois. Ne dépense pas la ressource réservée dans un autre craft.","optional":false,"tag":"PRÉPARATION","check":["Rotation consultée","Objet prioritaire choisi","Coût exact noté","Production affectée à la ressource manquante"]},{"id":"chip-shop","phase":"HEBDOMADAIRE","title":"Contrôle la rotation des chips et jewels","action":"Chaque rotation, compare les coûts au coffre et achète les jewels/chips structurants disponibles. Prépare les ressources de la rotation suivante plutôt que de découvrir le coût au dernier jour.","optional":false,"tag":"ROTATION","check":["Boutique de la semaine contrôlée","Ressources manquantes notées","Achat prioritaire effectué si possible"]},{"id":"w4-chip-equip","phase":"CHIPS / JEWELS","title":"Equipe et vérifie immédiatement l’achat","action":"Après l’achat préparé, place le chip sur le personnage qui exploite son effet ou active le jewel dans le Lab. Vérifie que le bonus est actif avant de considérer la rotation terminée.","optional":false,"tag":"VALIDATION","check":["Objet acheté","Objet équipé ou jewel actif","Effet vérifié"]},{"id":"breeding-eggs","phase":"BREEDING","title":"Claim les eggs avant le cap","action":"Ouvre Breeding, fais éclore les eggs disponibles et règle une fréquence de claim adaptée. Ne laisse pas la barre pleine pendant plusieurs jours.","optional":false,"tag":"ROUTINE","check":["Eggs réclamés","Capacité non pleine","Prochain pet ciblé"]},{"id":"breeding-pets","phase":"BREEDING","title":"Débloque les pets W1 dans l’ordre","action":"Utilise les gènes pour progresser le territoire W1. Garde les pets avec une meilleure puissance ou une compétence utile et recycle les doublons faibles.","optional":false,"tag":"PROGRESSION","check":["Plusieurs pets W1 débloqués","Equipe de combat constituée","Doublons faibles recyclés"]},{"id":"breeding-fence","phase":"BREEDING","title":"Place les bons pets au Fenceyard","action":"Utilise le Fenceyard pour les shiny pets lorsque le système est accessible. Choisis une durée cohérente et ne remplis pas tous les slots avec des espèces sans bonus utile.","optional":false,"tag":"LONG TERME","check":["Fenceyard rempli","Shiny bonus ciblé"]},{"id":"pet-battle","phase":"BREEDING","title":"Gagne les premières pet battles","action":"Compose une équipe avec dégâts, défense/soin et contrôle selon les compétences obtenues. Relance après une hausse de puissance plutôt que de répéter une composition bloquée.","optional":false,"tag":"COMBAT PET","check":["Premières battles gagnées","Nouvelle spice débloquée"]},{"id":"spice-collect","phase":"COOKING","title":"Affecte une équipe à chaque spice","action":"Place les pets dans les territoires ouverts et réclame les spices avant la capacité maximale. Priorise les spices nécessaires aux premières recettes.","optional":false,"tag":"PRODUCTION","check":["Chaque territoire possède une équipe","Spice production active","Aucune capacité durablement pleine"]},{"id":"w4-spice-target","phase":"BREEDING","title":"Produis une seule spice cible","action":"Choisis la kitchen ou recette prioritaire, note sa spice manquante, puis monte uniquement la team de territory qui produit cette spice. Claim avant le cap et garde les autres spices pour leurs coûts déjà planifiés.","optional":false,"tag":"FARM CIBLÉ","check":["Recette cible choisie","Spice exacte notée","Team affectée","Coût atteint"]},{"id":"kitchen-first","phase":"COOKING","title":"Achète et améliore les premières kitchens","action":"Répartis les spices entre vitesse de kitchen, nouveaux repas et upgrades. Une kitchen rapide vaut mieux qu’une recette très longue qui immobilise toute la production.","optional":false,"tag":"INSTALLATION","check":["Première kitchen active","Vitesse améliorée","Recette en cours"]},{"id":"w4-kitchen-check","phase":"COOKING","title":"Valide le gain avant l’upgrade suivant","action":"Après chaque achat de vitesse ou de kitchen, compare le temps de la recette cible. Si le temps ne baisse pas assez, arrête et redirige les spices vers le prochain meal ou bonus multiplicatif.","optional":false,"tag":"VALIDATION","check":["Temps avant noté","Upgrade acheté","Temps après comparé","Prochaine cible décidée"]},{"id":"meal-unlock","phase":"COOKING","title":"Découvre les meals accessibles","action":"Teste les combinaisons de spices et débloque les recettes rapides. Monte quelques niveaux de chaque meal bon marché pour accumuler des bonus account-wide.","optional":false,"tag":"MEALS","check":["Plusieurs meals découverts","Meals rapides montés","Aucune kitchen inactive"]},{"id":"meal-priority","phase":"COOKING","title":"Priorise vitesse, dégâts et progression","action":"Monte d’abord les meals qui accélèrent Cooking, améliorent les skills/account multipliers ou retirent un mur de dégâts/précision. Reporte les meals extrêmement lents.","optional":false,"tag":"PRIORITÉ","check":["Meal de vitesse ciblé","Temps du prochain niveau comparé au bénéfice"]},{"id":"elite-map","phase":"ELITE CLASSES","title":"Atteins Outskirts of Fallstar Isle","action":"Pousse ton meilleur personnage jusqu’à Eliteus. Active Killer Brightside, équipe les attaques et conserve 100 % précision et survie sur chaque nouvelle map.","optional":false,"tag":"OBJECTIF PRIORITAIRE","check":["Eliteus accessible","Quête Elite Class commencée"]},{"id":"elite-dk","phase":"ELITE CLASSES","title":"Transforme le Squire en Divine Knight","action":"Termine la quête d’Eliteus avec le Squire. Place immédiatement 1 point dans Divine Intervention et Orb of Remembrance puis configure la barre active.","optional":false,"tag":"CLASSE","character":"Squire → Divine Knight","talents":["Divine Intervention","Orb of Remembrance","Knightly Disciple"],"check":["DK obtenu","Compétences actives équipées"]},{"id":"elite-es","phase":"ELITE CLASSES","title":"Transforme le Wizard en Elemental Sorcerer","action":"Amène le Wizard à Eliteus, termine la quête et débloque Dimensional Wormhole. Garde un preset Divinity séparé pour W5.","optional":false,"tag":"CLASSE","character":"Wizard → Elemental Sorcerer","check":["ES obtenu","Wormhole équipé"]},{"id":"elite-sb","phase":"ELITE CLASSES","title":"Transforme le Bowman en Siege Breaker","action":"Termine Eliteus avec le Bowman et équipe Pirate Flag/Plunder lorsque disponibles. Continue Smithing et Catching sur le second preset.","optional":false,"tag":"CLASSE","character":"Bowman → Siege Breaker","check":["SB obtenu","Preset Catching conservé"]},{"id":"elite-bb","phase":"ELITE CLASSES","title":"Transforme le Barbarian en Blood Berserker","action":"Termine Eliteus, investis dans les talents Cooking et commence Chow seulement lorsque les kills demandés deviennent raisonnables.","optional":false,"tag":"CLASSE","character":"Barbarian → Blood Berserker","check":["BB obtenu","Preset Cooking créé"]},{"id":"elite-bm","phase":"ELITE CLASSES","title":"Transforme le Hunter en Beast Master","action":"Termine Eliteus, crée un preset Breeding et investis dans Arena Spirit/bonus de pets avant les talents marginaux.","optional":false,"tag":"CLASSE","character":"Hunter → Beast Master","check":["BM obtenu","Preset Breeding créé"]},{"id":"elite-bubo","phase":"ELITE CLASSES","title":"Transforme le Shaman en Bubonic Conjuror","action":"Termine Eliteus, équipe les poisons et Raise Dead. N’utilise le farm Cranium actif que si les poisons tuent rapidement.","optional":false,"tag":"CLASSE","character":"Shaman → Bubonic Conjuror","check":["Bubo obtenu","Preset Alchemy/Lab conservé","Barre active configurée"]},{"id":"elite-audit","phase":"ELITE CLASSES","title":"Vérifie les six Elite Classes","action":"Ouvre le roster et confirme DK, ES, SB, BB, BM et Bubo avant de créer un doublon. Le septième personnage reste réservé à la classe secrète.","optional":false,"tag":"VALIDATION","check":["DK","ES","SB","BB","BM","Bubo","Un seul Beginner secret"]},{"id":"w4-elite-presets","phase":"CLASSES ÉLITE","title":"Sépare combat et métier sur chaque Elite","action":"Pour chaque Elite obtenue, sauvegarde un preset combat avec les attaques sur la barre, puis un preset métier avec efficacité et talents du skill. Teste les deux avant de passer au personnage suivant.","optional":false,"tag":"ROSTER","check":["Preset combat testé","Preset métier testé","Barre Auto vérifiée"]},{"id":"w4-purp","phase":"PUSH MAP PAR MAP","title":"Traverse Purp Mushrooms et TV","action":"Utilise DK actif si la map permet à Divine Intervention de respawn correctement ; sinon compare ES et AFK. Termine chaque compteur avec Brightside actif.","optional":false,"tag":"MAPS","check":["Purp Mushrooms terminés","TV terminés","Brightside vérifié"]},{"id":"w4-donut","phase":"PUSH MAP PAR MAP","title":"Traverse Donuts et Soda Cans","action":"Contrôle précision, survie et kills/heure. Mets à jour l’arme avant l’armure si tes dégâts sont le principal mur.","optional":false,"tag":"MAPS","check":["Donuts terminés","Soda Cans terminés","Arme contrôlée"]},{"id":"w4-cubes","phase":"PUSH MAP PAR MAP","title":"Traverse Gelatinous Cuboids et Choccies","action":"Garde les autres personnages dans le Lab sauf ceux nécessaires aux Elite Classes. Réorganise les lignes après chaque sortie.","optional":false,"tag":"MAPS","check":["Cuboids terminés","Choccies terminés","Lab toujours connecté"]},{"id":"tome-open","phase":"ACCOUNT-WIDE","title":"Active et inspecte le Tome","action":"Réclame les catégories gratuites et utilise les scores comme diagnostic : améliore d’abord les systèmes très en retard qui demandent peu de temps.","optional":false,"tag":"DIAGNOSTIC","check":["Tome accessible","Récompenses faciles réclamées","Trois catégories faibles identifiées"]},{"id":"rift-entry","phase":"RIFT","title":"Ouvre l’accès au Rift sans bloquer le push","action":"Entre depuis la zone d’Octodar lorsque disponible. Termine uniquement les objectifs rapides à ton niveau, puis retourne au push dès qu’un palier exige trop de temps.","optional":true,"tag":"OPTIONNEL","quest":"OPTIONNELLE","check":["Rift visité","Premier bonus rentable obtenu ou objectif reporté"]},{"id":"troll-key","phase":"BOSS","title":"Débloque la clé du Troll","action":"Termine la ligne obligatoire W4 menant au boss et conserve les drops de quête. Vérifie l’accès avant de déplacer tout le roster hors du Lab.","optional":false,"tag":"QUÊTE OBLIGATOIRE","quest":"OBLIGATOIRE","check":["Clé du Troll obtenue","Boss accessible"]},{"id":"troll-check","phase":"BOSS","title":"Prépare les mini-épreuves du Troll","action":"Equipe meilleure arme, nourriture, précision et attaques variées. Lis l’objectif affiché pendant chaque mini-épreuve : mobs, cibles ou plateformes doivent être réussis avant de burst.","optional":false,"tag":"VALIDATION","gear":["Meilleure arme accessible","Nourriture","Cards boss/précision","Attaques multiples sur la barre"],"check":["100 % précision","Survie suffisante","Mécaniques comprises"]},{"id":"w4-troll-farm","phase":"BOSS","title":"Corrige un seul échec du Troll à la fois","action":"Si le combat échoue, identifie la cause exacte : précision, survie, dégâts ou mécanique. Farm uniquement le système correspondant, reteste, puis passe au problème suivant au lieu d’améliorer tout le compte simultanément.","optional":false,"tag":"DIAGNOSTIC","check":["Cause mesurée","Une amélioration ciblée","Nouveau test effectué"]},{"id":"gear","phase":"ÉQUIPEMENT","title":"Prépare le Troll","action":"Mets à jour l’arme W4, garde Amarok/Chizoar selon tes ressources, équipe accuracy cards et nourriture.","why":"Le Troll teste surtout la compréhension de ses mini-épreuves.","optional":false},{"id":"troll","phase":"BOSS","title":"Bats le Troll Normal","action":"Réussis chaque mini-jeu affiché (cibles, plateformes, mobs) pour rendre le Troll vulnérable, puis burst.","why":"La victoire ouvre Smolderin’ Plateau.","optional":false},{"id":"onyx","phase":"RETOUR","title":"Prépare les Onyx Statues","action":"Après les unlocks Rift requis, donne une pile de 20 000 statues au Statue Man via la quête Monolith, une statue à la fois.","why":"Onyx double la statue et renforce les dépôts futurs.","optional":true,"tag":"LONG TERME"}]},{"slug":"w5","number":"05","name":"Smolderin' Plateau","subtitle":"Divinity, Sailing et The Hole","accent":"#ec845e","goal":"Monter Divinity, Sailing et Gaming, puis vaincre Kattlekruk.","gate":["Divinity 40 visée sur tous","Bear/Goat Gods exploités","Sailing jamais capée","Kattlekruk vaincu"],"steps":[{"id":"w5-enter","phase":"ARRIVÉE","title":"Entre dans Smolderin’ Plateau sans vider tes pièces","action":"Après le Troll, active W5 et ouvre Divinity, Sailing et Gaming. Au magasin, relève seulement les prix des coffres, bags, nourriture et outils ; reporte les achats jusqu’au budget suivant.","optional":false,"tag":"DÉCOUVERTE","check":["Trois skills ouverts","Prix du magasin relevés","Aucun achat impulsif"]},{"id":"w5-money","phase":"ARGENT","title":"Finance uniquement les achats W5 utiles","action":"Choisis une seule amélioration de capacité qui empêche un cap, ajoute une pile de nourriture adaptée et l’outil immédiatement nécessaire. Farm ta meilleure map W4, le Troll ou le début W5 avec 100 % précision/survie jusqu’au total affiché. Conserve les drops W5 pour Sailing, Divinity, crafts et quêtes.","optional":false,"tag":"FARM CIBLÉ","check":["Trois achats maximum choisis","Prix total calculé","Somme atteinte","Drops W5 conservés"]},{"id":"w5-shopping","phase":"ARRIVÉE","title":"Achète puis retourne aux trois skills","action":"Achète nourriture en premier, puis l’amélioration de capacité choisie, puis l’outil utile. N’achète pas tous les coffres et bags d’un coup : chaque achat suivant doit résoudre un cap mesuré.","optional":false,"tag":"ACHAT","check":["Nourriture équipée","Cap de stockage corrigé","Outil utile équipé","Réserve non vidée"]},{"id":"w5-three-loop","phase":"ARRIVÉE","title":"Fais une première boucle complète des trois skills","action":"Claim Divinity, ouvre les chests Sailing puis récolte Gaming, dans cet ordre. Dépense uniquement ce qui empêche un cap et replace ensuite tous les personnages/bateaux/plants avant de quitter la ville.","optional":false,"tag":"INSTALLATION","check":["Divinity relancée","Bateaux relancés","Gaming récolté","Aucun système laissé inactif"]},{"id":"div-place","phase":"DIVINITY","title":"Place tout le roster sauf le pusher à l’autel","action":"Mets immédiatement les personnages disponibles en méditation. Garde seulement ton meilleur pusher dehors afin de commencer les portails pendant que le time-gate avance.","optional":false,"tag":"INSTALLATION","character":"Tout le roster sauf pusher","check":["Un pusher dehors","Tous les autres méditent","Aucun personnage inactif sans objectif"]},{"id":"div-style1","phase":"DIVINITY","title":"Débloque le premier style de méditation","action":"Réclame les gains régulièrement jusqu’au premier style. Equipe le style offrant le meilleur gain réel à ce stade et contrôle le temps avant le prochain niveau.","optional":false,"tag":"STYLE","check":["Premier style débloqué","Style équipé sur chaque méditant"]},{"id":"div-style-prog","phase":"DIVINITY","title":"Change de style aux bons paliers","action":"Utilise les styles orientés EXP pour monter les niveaux, puis les styles orientés points lorsque l’objectif est le prochain God. Ne laisse pas un ancien style par oubli.","optional":false,"tag":"OPTIMISATION","check":["Style de chaque personnage vérifié","Objectif EXP ou points défini"]},{"id":"god-1","phase":"DIVINITY","title":"Débloque les premiers Gods","action":"Accumule les points dans l’ordre de la Divinity table et lie chaque nouveau God au personnage qui profite réellement de son effet. Ne copie pas le même lien sur tout le roster sans raison.","optional":false,"tag":"GODS","check":["Premier God débloqué","Liens attribués selon les rôles"]},{"id":"bear-link","phase":"DIVINITY","title":"Utilise Bear pour compter dans le Lab","action":"Lie Bear aux personnages qui doivent bénéficier du réseau Lab tout en combattant ou skilling hors des tubes. Vérifie ensuite que les nodes restent connectés.","optional":false,"tag":"GOD CLÉ","character":"Personnages sortis du Lab","check":["Bear lié","Réseau Lab toujours actif","Personnage libre de son tube"]},{"id":"goat-link","phase":"DIVINITY","title":"Utilise Goat pour monter Lab et Divinity ensemble","action":"Quand Goat est disponible, place les personnages concernés dans le Lab avec ce lien afin de gagner simultanément les deux expériences.","optional":false,"tag":"GOD CLÉ","character":"Personnages sous niveau Lab/Divinity cible","check":["Goat lié","Personnages uploadés","Deux gains d’EXP confirmés"]},{"id":"div-40","phase":"DIVINITY","title":"Fais progresser chaque personnage vers Divinity 40","action":"Ne valide pas W5 comme terminé avec seulement le pusher avancé. Fais tourner les liens/styles jusqu’à atteindre progressivement le niveau 40 sur tous.","optional":false,"tag":"OBJECTIF COMPTE","character":"Tout le roster","check":["Chaque personnage possède un plan vers niveau 40","Personnages déjà niveau 40 réaffectés intelligemment"]},{"id":"sail-boat1","phase":"SAILING","title":"Envoie le premier boat immédiatement","action":"Choisis l’île la plus proche, affecte un captain et lance le voyage. Un boat au port ne produit ni chests ni progression.","optional":false,"tag":"INSTALLATION","check":["Captain équipé","Boat en voyage","Destination accessible sélectionnée"]},{"id":"sail-claim","phase":"SAILING","title":"Ouvre les chests avant que le stockage cape","action":"Réclame régulièrement les chests, améliore la capacité si elle sature pendant tes absences et dépense les ressources au lieu de les laisser inutilisées.","optional":false,"tag":"ROUTINE","check":["Stockage non capé","Chests ouverts","Ressources dépensées"]},{"id":"w5-sail-cap","phase":"SAILING","title":"Dimensionne la capacité à ton absence","action":"Observe le temps avant saturation des chests, compare-le à ta durée habituelle hors ligne et achète de la capacité seulement si elle cape avant ton retour. Sinon, investis dans vitesse et nouvelles îles.","optional":false,"tag":"VALIDATION","check":["Temps avant cap lu","Durée AFK comparée","Capacité ou vitesse choisie"]},{"id":"sail-captains","phase":"SAILING","title":"Recrute et remplace les captains","action":"Compare vitesse, loot et bonus spéciaux. Remplace un captain faible seulement si le nouveau améliore le temps réel ou la qualité de la route ciblée.","optional":false,"tag":"CAPTAINS","check":["Chaque boat possède un captain","Captains faibles identifiés"]},{"id":"sail-route","phase":"SAILING","title":"Garde des voyages courts et rentables","action":"Vise un temps de trajet adapté à ta fréquence de claim. Si une île lointaine multiplie trop le temps pour peu de chance, améliore d’abord boats et captains.","optional":false,"tag":"ROUTES","check":["Aucun trajet inutilement long","Prochaine île ciblée"]},{"id":"artifact-speed","phase":"SAILING","title":"Priorise les artifacts d’accélération","action":"Cherche d’abord les artifacts qui renforcent Sailing, talents, Alchemy ou progression globale. Passe à l’ancienneté supérieure seulement lorsque la chance est raisonnable.","optional":false,"tag":"ARTIFACTS","check":["Artifact structurant ciblé","Chance d’obtention contrôlée"]},{"id":"artifact-claim","phase":"SAILING","title":"Vérifie les artifacts après chaque nouvelle île","action":"Ouvre l’interface d’île, identifie l’artifact manquant et affecte assez de boats pour l’obtenir sans arrêter toute la progression vers l’île suivante.","optional":false,"tag":"ARTIFACTS","check":["Artifacts des îles ouvertes inspectés","Flotte répartie entre progression et farm"]},{"id":"gaming-claim","phase":"GAMING","title":"Récolte les plants avant saturation","action":"Claim les plants, conserve les évolutions utiles et recycle les faibles. Reviens assez souvent pour que les emplacements ne restent pas pleins.","optional":false,"tag":"ROUTINE","check":["Tous les plants récoltés","Emplacements replantés"]},{"id":"gaming-import","phase":"GAMING","title":"Achète les imports structurants","action":"Dépense les bits sur vitesse, gain et nouvelles mécaniques avant les améliorations faibles. Lis le prochain coût avant de vider toute la monnaie.","optional":false,"tag":"IMPORTS","check":["Upgrade de vitesse/gain acheté","Prochain palier identifié"]},{"id":"w5-bit-target","phase":"GAMING","title":"Économise pour un seul Import","action":"Choisis l’Import qui débloque la prochaine mécanique ou multiplie le bit gain, note son coût, puis refuse les petits upgrades jusqu’à l’atteindre. Après achat, mesure le nouveau gain avant de choisir la cible suivante.","optional":false,"tag":"FARM CIBLÉ","check":["Import choisi","Coût noté","Bits économisés","Gain après achat vérifié"]},{"id":"gaming-dk","phase":"GAMING","title":"Utilise les synergies du Divine Knight","action":"Sur le preset Gaming du DK, monte les talents qui accélèrent Gaming avant les dégâts personnels. Equipe ce preset lors des gros claims concernés.","optional":false,"tag":"CLASSE","character":"Divine Knight","check":["Preset Gaming créé","Talents Gaming investis"]},{"id":"slab-open","phase":"SLAB","title":"Inspecte le Slab et ses objets manquants","action":"Trie les entrées jamais obtenues. Commence par acheter ou craft une fois les objets W1–W3 bon marché, puis place-les au sol/ramasse-les si nécessaire pour l’enregistrement.","optional":false,"tag":"COLLECTION","check":["Slab ouvert","Liste d’objets faciles établie","Premiers manquants enregistrés"]},{"id":"w5-slab-family","phase":"SLAB","title":"Complète une seule famille d’objets","action":"Choisis shops W1, crafts W1 ou équipements W2, liste les objets jamais obtenus, puis achète/craft/ramasse chaque objet de cette famille avant d’en ouvrir une autre. Protège les quest items irremplaçables.","optional":false,"tag":"COLLECTION","check":["Famille choisie","Manquants listés","Objets enregistrés","Quest items protégés"]},{"id":"slab-gear","phase":"SLAB","title":"Enregistre les anciennes armes et armures","action":"Craft chaque pièce bon marché une fois sans gaspiller les matériaux time-gated. Vérifie l’enregistrement avant de vendre ou recycler l’objet.","optional":false,"tag":"COLLECTION","check":["Anvil Tabs anciennes contrôlées","Objets abordables enregistrés"]},{"id":"w5-suggma","phase":"PUSH MAP PAR MAP","title":"Traverse Suggmas et Citringes","action":"Active Brightside, maintiens 100 % précision et compare DK/ES selon la géométrie. Termine les portails tout en laissant le reste du roster progresser Divinity.","optional":false,"tag":"MAPS","check":["Suggmas terminés","Citringes terminés","Divinity toujours active"]},{"id":"w5-moles","phase":"PUSH MAP PAR MAP","title":"Traverse Moles et Stiltmoles","action":"Améliore Shaquracy, weapon et damage bubbles si les kills/heure chutent. Prépare déjà une barre AoE capable de tuer les moles du boss.","optional":false,"tag":"MAPS","check":["Moles terminés","Stiltmoles terminés","AoE configurée"]},{"id":"w5-wurms","phase":"PUSH MAP PAR MAP","title":"Atteins les Tremor Wurms","action":"Pousse les dernières maps avec le personnage au meilleur débit réel. Conserve les matériaux du boss et de la meilleure arme au lieu de les consommer en crafts secondaires.","optional":false,"tag":"MAP","check":["Tremor Wurms accessibles","Matériaux clés conservés"]},{"id":"hole-open","phase":"THE HOLE","title":"Entre dans Caverns Below","action":"Ouvre The Hole depuis W5, parle aux villagers et réclame les premières lanternes. Ce système ne mobilise aucun personnage : démarre-le sans attendre.","optional":false,"tag":"ACCOUNT-WIDE","check":["The Hole accessible","Premiers villagers recrutés","Lanternes disponibles"]},{"id":"hole-villagers","phase":"THE HOLE","title":"Fais travailler chaque villager","action":"Affecte les ressources aux upgrades ouvrant de nouvelles fonctions, vitesse et capacité. Ne concentre pas tout sur une statistique si un unlock exige plusieurs villagers.","optional":false,"tag":"VILLAGERS","check":["Chaque villager accessible progresse","Prochain unlock noté"]},{"id":"hole-lantern","phase":"THE HOLE","title":"Dépense les lanternes quotidiennement","action":"Utilise les lanternes sur les caverns qui débloquent un système ou un multiplicateur prioritaire. Ne laisse pas les gains quotidiens expirer.","optional":false,"tag":"QUOTIDIEN","check":["Lanternes du jour dépensées","Cavern cible choisie"]},{"id":"hole-schematic","phase":"THE HOLE","title":"Achète les schematics multiplicatifs","action":"Priorise vitesse de villagers, capacité, gains globaux et ouvertures de caverns. Reporte les bonus minuscules tant qu’un nouveau système est proche.","optional":false,"tag":"PRIORITÉ","check":["Schematics disponibles inspectés","Upgrade structurant acheté"]},{"id":"hole-measure","phase":"THE HOLE","title":"Configure Measurement selon le goulot","action":"Affecte les mesures aux bonus qui retirent le blocage actuel : dégâts, skill efficiency, printer ou système W5. Reviens après chaque nouveau palier.","optional":false,"tag":"OPTIMISATION","check":["Measurement configuré","Goulot actuel ciblé"]},{"id":"w5-hole-target","phase":"THE HOLE","title":"Affecte les lanternes à un seul déblocage","action":"Lis les conditions des caverns accessibles, choisis celle qui ouvre le meilleur système, puis dépense les lanternes uniquement jusqu’à ce seuil. Une fois atteint, recompare avant la prochaine dépense.","optional":false,"tag":"ANTI-DISPERSION","check":["Cavern cible choisie","Seuil exact noté","Lanternes affectées","Déblocage obtenu ou progression mesurée"]},{"id":"kruk-key","phase":"BOSS","title":"Débloque l’accès à Kattlekruk","action":"Termine la ligne obligatoire W5 et conserve la clé. Vérifie que le portail du boss est accessible avant de préparer le burst.","optional":false,"tag":"QUÊTE OBLIGATOIRE","quest":"OBLIGATOIRE","check":["Clé Kattlekruk obtenue","Boss accessible"]},{"id":"kruk-aoe","phase":"BOSS","title":"Teste ton nettoyage des moles","action":"Sur une map de Moles, vérifie que tes AoE tuent vite des deux côtés. Si les ennemis survivent longtemps, améliore dégâts et cooldowns avant le boss.","optional":false,"tag":"TEST","character":"DK/ES ou meilleur clear","check":["Vagues de moles éliminées rapidement","AoE correctement ordonnées"]},{"id":"kruk-check","phase":"BOSS","title":"Valide le build Kattlekruk","action":"Equipe meilleure arme, dégâts, move speed et nourriture. Le boss est prêt seulement si tu peux empêcher presque tous les soigneurs d’atteindre le centre.","optional":false,"tag":"VALIDATION","gear":["Meilleure arme","Nourriture","Cards dégâts/boss","AoE sur la barre"],"check":["100 % précision","Survie suffisante","Moles contrôlées des deux côtés"]},{"id":"w5-kruk-farm","phase":"BOSS","title":"Prépare le clear Kruk mesuré","action":"Fais une tentative, mesure si les moles passent à cause du manque d’AoE ou de dégâts mono-cible, puis améliore uniquement le point faible. Reviens avec nourriture, barre Auto et preset vérifiés.","optional":false,"tag":"DIAGNOSTIC","check":["Cause de l’échec identifiée","Build ciblé corrigé","Nouveau test effectué"]},{"id":"kruk","phase":"BOSS","title":"Bats Kattlekruk Normal","action":"Tue continuellement les moles des deux côtés, garde tes AoE au centre et burst le boss entre les vagues.","why":"La victoire ouvre Spirited Valley.","optional":false},{"id":"rotation","phase":"ROUTINE","title":"Organise tes personnages","action":"Un pusher actif ; autres en Divinity jusqu’à 40 puis Lab jusqu’à 75 ; spécialistes sortent seulement pour samples et matériaux.","why":"Évite de laisser un héros sans objectif account-wide.","optional":false}]},{"slug":"w6","number":"06","name":"Spirited Valley","subtitle":"Farming, Sneaking et Summoning","accent":"#e990b8","goal":"Faire tourner les trois skills W6, obtenir les Master Classes et vaincre Emperor.","gate":["Farming sans parcelle vide","Sneaking sur tous les étages accessibles","Summoning battles avancées","Emperor vaincu"],"steps":[{"id":"w6-enter","phase":"ARRIVÉE","title":"Entre dans Spirited Valley","action":"Après Kattlekruk, active W6 et parle aux NPC de la ville. Ouvre Farming, Sneaking et Summoning avant de placer ton pusher.","optional":false,"tag":"DÉCOUVERTE","check":["Ville W6 débloquée","Trois skills ouverts","Magasin contrôlé"]},{"id":"farm-plot1","phase":"FARMING","title":"Plante toutes les parcelles disponibles","action":"Choisis les seeds de départ, remplis chaque plot et vérifie le temps de croissance. Une parcelle vide ne produit ni crops ni progression.","optional":false,"tag":"INSTALLATION","check":["Aucune parcelle vide","Temps de croissance connu"]},{"id":"farm-claim","phase":"FARMING","title":"Récolte avant le cap de croissance utile","action":"Claim les crops lorsque le prochain cycle ou mutation est rentable. Replante immédiatement et adapte la seed à la durée de ta prochaine absence.","optional":false,"tag":"ROUTINE","check":["Crops récoltées","Toutes les parcelles replantées"]},{"id":"farm-budget","phase":"FARMING","title":"Constitue le stock du prochain Market upgrade","action":"Ouvre Market, choisis un seul upgrade structurant et note son coût exact en crops. Bloque les parcelles nécessaires sur ces crops jusqu’au total demandé ; ne consomme pas ce stock dans Land ou un autre upgrade entre-temps.","optional":false,"tag":"FARM CIBLÉ","check":["Upgrade unique choisi","Coût exact noté","Parcelles affectées","Stock réservé"]},{"id":"farm-buy-check","phase":"FARMING","title":"Achète puis mesure le Market upgrade","action":"Dépense le stock réservé sur l’upgrade prévu, replante immédiatement toutes les parcelles et compare croissance/rendement avant et après. Choisis seulement ensuite le prochain coût.","optional":false,"tag":"VALIDATION","check":["Upgrade acheté","Parcelles replantées","Gain comparé","Nouvelle cible choisie"]},{"id":"farm-market","phase":"FARMING","title":"Achète les premiers Market upgrades","action":"Priorise vitesse de croissance, rendement, nouvelles parcelles et progression de seeds. Evite de vider toute la monnaie sur un bonus marginal.","optional":false,"tag":"PRIORITÉ","check":["Upgrade de vitesse acheté","Prochain coût structurant identifié"]},{"id":"farm-land","phase":"FARMING","title":"Débloque de nouvelles terres","action":"Accumule les crops nécessaires à Land et ouvre les parcelles supplémentaires dès que leur coût reste raisonnable. Remplis-les immédiatement.","optional":false,"tag":"EXPANSION","check":["Prochaine Land ciblée","Nouvelle parcelle plantée si débloquée"]},{"id":"farm-seeds","phase":"FARMING","title":"Fais évoluer les seed tiers","action":"Utilise les crops demandées pour débloquer les seeds suivantes. Ne reste pas indéfiniment sur une plante rapide si une nouvelle famille est accessible.","optional":false,"tag":"SEEDS","check":["Seed tier suivant identifié","Crops requises réservées"]},{"id":"farm-crop-set","phase":"FARMING","title":"Complète les familles de crops","action":"Découvre chaque crop d’une famille pour ses bonus, puis passe à la famille suivante. Reviens farm une crop précise seulement pour un upgrade concret.","optional":false,"tag":"COLLECTION","check":["Famille actuelle inspectée","Crop manquante ciblée"]},{"id":"farm-db","phase":"FARMING","title":"Crée le preset Farming du Death Bringer","action":"Après la Master Class, investis dans les talents Farming/account-wide sur un preset séparé. Equipe ce preset lors des gros claims si ses effets l’exigent.","optional":false,"tag":"CLASSE","character":"Death Bringer","check":["Preset Farming créé","Talents structurants prioritaires"]},{"id":"sneak-untie","phase":"SNEAKING","title":"Détache les premiers ninjas","action":"Entre dans Sneaking, libère les personnages disponibles et équipe chacun d’un objet offensif ou utilitaire. Aucun ninja débloqué ne doit rester sans action.","optional":false,"tag":"INSTALLATION","character":"Tout le roster","check":["Ninjas accessibles détachés","Chaque ninja possède un équipement"]},{"id":"sneak-floor","phase":"SNEAKING","title":"Monte un étage seulement avec une bonne survie","action":"Compare Detection et Knockout Time. Si toute l’équipe tombe trop vite, farm l’étage précédent pour Jade, XP et meilleur équipement.","optional":false,"tag":"PROGRESSION","stats":["Knockout Time acceptable","Chance de détection contrôlée"],"check":["Etage adapté choisi","Equipe non bloquée en KO permanent"]},{"id":"sneak-items","phase":"SNEAKING","title":"Equipe Nunchaku et Lotus selon le rôle","action":"Donne les meilleurs objets de dégâts/stealth aux ninjas qui ouvrent l’étage. Utilise les objets de gain sur les farmers stables et recycle les pièces nettement inférieures.","optional":false,"tag":"ÉQUIPEMENT","check":["Meilleurs objets équipés","Doublons faibles recyclés"]},{"id":"sneak-inventory","phase":"SNEAKING","title":"Equipe un personnage à la fois","action":"Trie les items par Stealth puis détection/EXP, équipe le ninja qui bloque l’étage actuel et vérifie son taux avant de toucher au suivant. Recycle uniquement les doublons clairement inférieurs.","optional":false,"tag":"ÉQUIPEMENT","check":["Personnage bloqué identifié","Item comparé","Taux amélioré","Doublons sûrs recyclés"]},{"id":"sneak-jade","phase":"SNEAKING","title":"Dépense le Jade dans l’Emporium","action":"Priorise les unlocks de système, multiplicateurs globaux et améliorations d’anciens mondes. Garde assez de Jade pour le prochain achat structurant visible.","optional":false,"tag":"EMPORIUM","check":["Emporium inspecté","Upgrade structurant acheté","Prochain coût noté"]},{"id":"sneak-jade-target","phase":"SNEAKING","title":"Verrouille le prochain achat Jade","action":"Choisis un seul achat Emporium structurant, note son coût et garde le Jade jusqu’au seuil. Ignore les améliorations marginales qui repousseraient le déblocage.","optional":false,"tag":"FARM CIBLÉ","check":["Achat choisi","Coût noté","Jade réservé","Achat obtenu"]},{"id":"sneak-charms","phase":"SNEAKING","title":"Equipe et améliore les charms utiles","action":"Compare les effets réels sur Jade, stealth et progression d’étage. Ne conserve pas un charm rare si son effet ne sert pas l’objectif actuel.","optional":false,"tag":"CHARMS","check":["Charms équipés sur les ninjas actifs","Objectif Jade ou étage défini"]},{"id":"sneak-ww","phase":"SNEAKING","title":"Prépare le preset Sneaking du Wind Walker","action":"Après la Master Class, sépare les talents Sneaking du build combat/Form. Vérifie le bon preset avant chaque claim important.","optional":false,"tag":"CLASSE","character":"Wind Walker","check":["Preset Sneaking créé","Bon preset équipé au claim"]},{"id":"sum-start","phase":"SUMMONING","title":"Lance les premières Summoning battles","action":"Collecte les familiars/essences disponibles, place les unités selon leur coût et termine les combats de départ. Réclame chaque winner bonus.","optional":false,"tag":"INSTALLATION","check":["Première battle gagnée","Winner bonus réclamé"]},{"id":"sum-essence","phase":"SUMMONING","title":"Dépense les essences par couleur","action":"Améliore mana de départ, régénération, puissance et nouvelles unités selon le mur actuel. Ne répartis pas tout uniformément si une battle demande un pic précis.","optional":false,"tag":"UPGRADES","check":["Essences dépensées","Goulot mana ou dégâts identifié"]},{"id":"sum-next-battle","phase":"SUMMONING","title":"Investis pour la prochaine battle seulement","action":"Lance la prochaine battle, repère si tu manques de mana initial, régénération ou puissance, puis dépense l’essence uniquement dans cette statistique. Reteste avant un nouvel investissement.","optional":false,"tag":"DIAGNOSTIC","check":["Battle testée","Goulot identifié","Essence ciblée","Résultat retesté"]},{"id":"sum-deck","phase":"SUMMONING","title":"Adapte le deck à la battle","action":"Mets les unités bon marché pour stabiliser la ligne, puis les unités fortes lorsque le mana le permet. Change de composition après un échec au lieu de répéter exactement la même ouverture.","optional":false,"tag":"STRATÉGIE","check":["Deck adapté","Ordre de pose défini"]},{"id":"sum-bonuses","phase":"SUMMONING","title":"Réclame et vérifie chaque winner bonus","action":"Après une victoire, ouvre les bonus account-wide et note le prochain combat. Reviens seulement après une amélioration significative de mana ou puissance.","optional":false,"tag":"ACCOUNT-WIDE","check":["Bonus réclamé","Prochaine battle identifiée"]},{"id":"sum-ac","phase":"SUMMONING","title":"Crée le preset Summoning de l’Arcane Cultist","action":"Après la Master Class, investis dans les talents Summoning sur un preset dédié et conserve séparément le build Bubo actif.","optional":false,"tag":"CLASSE","character":"Arcane Cultist","check":["Preset Summoning créé","Preset Bubo préservé"]},{"id":"w6-portal-roster","phase":"PORTAILS","title":"Lis la condition de chaque portail multi-personnages","action":"Certains portails exigent des kills sur plusieurs personnages. Note le nombre de personnages et répartis uniquement ceux requis avant de recentrer les autres sur leurs time-gates.","optional":false,"tag":"ROSTER","check":["Condition du portail lue","Personnages requis affectés"]},{"id":"w6-level-roster","phase":"ROSTER","title":"Remonte les personnages laissés derrière","action":"Equipe armes, nourriture et précision aux personnages secondaires puis ouvre les maps nécessaires. Ne force pas un portail W6 avec un personnage encore équipé W2.","optional":false,"tag":"RATTRAPAGE","character":"Personnages secondaires","check":["100 % précision sur leur map","Arme et nourriture mises à jour"]},{"id":"master-map","phase":"MASTER CLASSES","title":"Atteins la zone des Master Classes","action":"Pousse les classes éligibles jusqu’au NPC de promotion. Utilise le meilleur équipement partagé et les portails déjà ouverts pour accélérer chaque trajet.","optional":false,"tag":"PRIORITÉ","check":["NPC Master Class accessible","Trois classes éligibles prêtes"]},{"id":"master-db","phase":"MASTER CLASSES","title":"Transforme Blood Berserker en Death Bringer","action":"Termine la quête, débloque Wraith Form et commence les bones sans reset précipité. Priorise les bonus account-wide et Skull of Major Talent.","optional":false,"tag":"CLASSE","character":"Blood Berserker → Death Bringer","check":["Death Bringer obtenu","Wraith Form inspectée","Prochain palier bones défini"]},{"id":"master-ww","phase":"MASTER CLASSES","title":"Transforme Beast Master en Wind Walker","action":"Termine la quête, débloque Tempest Form et commence Dust/Medallions. Garde les talents Sneaking sur un preset séparé.","optional":false,"tag":"CLASSE","character":"Beast Master → Wind Walker","check":["Wind Walker obtenu","Tempest Form inspectée"]},{"id":"master-ac","phase":"MASTER CLASSES","title":"Transforme Bubonic Conjuror en Arcane Cultist","action":"Termine la quête, ouvre Arcanist Form et les Tachyons. Préserve un preset complet Bubo/Cranium Cooking.","optional":false,"tag":"CLASSE","character":"Bubonic Conjuror → Arcane Cultist","check":["Arcane Cultist obtenu","Arcanist Form inspectée","Preset Bubo conservé"]},{"id":"forms-rule","phase":"MASTER CLASSES","title":"Ne reset une Form que pour un vrai palier","action":"Avant Wraith, Tempest ou Arcanist reset, compare le temps perdu au bonus obtenu. Termine les objectifs rapides et sécurise le prochain multiplicateur account-wide.","optional":false,"tag":"RÈGLE","check":["Prochain palier identifié","Reset rentable confirmé"]},{"id":"w6-sprout","phase":"PUSH MAP PAR MAP","title":"Traverse Sprout Spirits et Ricecakes","action":"Maintiens Brightside, précision et survie. Utilise la classe active offrant le meilleur respawn/clear sur la géométrie de la map.","optional":false,"tag":"MAPS","check":["Sprout Spirits terminés","Ricecakes terminés"]},{"id":"w6-river","phase":"PUSH MAP PAR MAP","title":"Traverse River Spirits et Baby Trolls","action":"Vérifie les conditions multi-personnages avant de déplacer tout le roster. Mets à jour l’arme et Alchemy si les kills/heure s’effondrent.","optional":false,"tag":"MAPS","check":["River Spirits terminés","Baby Trolls terminés","Condition roster validée"]},{"id":"w6-leek","phase":"PUSH MAP PAR MAP","title":"Traverse Leek Spirits et les zones tardives","action":"Conserve les drops rares et matériaux Emperor. Alterne push et retour sur Farming/Summoning/Sneaking dès qu’un nouveau multiplicateur est prêt.","optional":false,"tag":"MAPS","check":["Leek Spirits terminés","Maps tardives accessibles","Skills W6 toujours actifs"]},{"id":"emperor-key","phase":"BOSS","title":"Débloque l’accès à Emperor","action":"Termine les conditions et quêtes obligatoires W6. Refais le boss si nécessaire pour activer ensuite l’accès W7.","optional":false,"tag":"QUÊTE OBLIGATOIRE","quest":"OBLIGATOIRE","check":["Accès Emperor ouvert","Condition W7 comprise"]},{"id":"emperor-pattern","phase":"BOSS","title":"Apprends chaque phase sans gaspiller les ressources","action":"Fais un essai d’observation : identifie invocations, zones dangereuses et fenêtres de burst. Ajuste la barre avant l’essai sérieux.","optional":false,"tag":"MÉCANIQUES","check":["Phases reconnues","Invocations prioritaires identifiées","Barre ajustée"]},{"id":"emperor-check","phase":"BOSS","title":"Valide le build Emperor","action":"Equipe meilleure arme, nourriture, move speed, cards boss et précision. Garde les bursts pour les fenêtres sûres et assez de survie pour apprendre les patterns.","optional":false,"tag":"VALIDATION","gear":["Meilleure arme accessible","Nourriture W6","Cards boss/précision","Attaques/Form adaptées"],"check":["100 % précision","Survie suffisante","Inventaire libre","Accès boss disponible"]},{"id":"w6-emperor-farm","phase":"BOSS","title":"Farm uniquement le seuil manquant pour l’Empereur","action":"Teste le boss, relève la condition non satisfaite ou la phase qui bloque, puis affecte Farming, Sneaking, Summoning ou combat à ce seul seuil. Reviens dès qu’il est atteint, sans attendre de maxer les trois skills.","optional":false,"tag":"DIAGNOSTIC","check":["Blocage exact noté","Un seul système affecté","Seuil atteint","Nouvelle tentative faite"]},{"id":"emperor","phase":"BOSS","title":"Bats Emperor Normal","action":"Apprends les patterns de chaque phase, détruis les invocations prioritaires et garde tes bursts pour les fenêtres sûres.","why":"La victoire ouvre Shimmerfin Deep.","optional":false},{"id":"catchup","phase":"RETOUR","title":"Fais un audit du compte","action":"Re-sample, monte les bubbles 100M+ avec Boron, pousse Meals, Lab 75, Divinity 40, Rift et artifacts.","why":"W7 suppose que les multiplicateurs des anciens mondes tournent ensemble.","optional":false}]},{"slug":"w7","number":"07","name":"Shimmerfin Deep","subtitle":"Research et Spelunking","accent":"#65d6cc","goal":"Explorer les 12 maps, développer Research et Spelunking, puis ouvrir le contenu 2026.","gate":["Spelunking automatisé","Research grid optimisée","Map bonuses Master Class actifs","Cavern/Green Water ouverts"],"steps":[{"id":"w7-reenter","phase":"ARRIVÉE","title":"Refais Emperor pour activer l’accès W7","action":"Si le portail W7 n’apparaît pas après ta première victoire, retourne battre Emperor selon la condition affichée. Entre ensuite à Shimmerfin Deep.","optional":false,"tag":"PRÉREQUIS","check":["Emperor revalidé si nécessaire","Ville W7 accessible"]},{"id":"w7-npc","phase":"ARRIVÉE","title":"Parle à tous les NPC et ouvre les interfaces","action":"Visite les NPC de ville et de la première map, puis ouvre Spelunking et les nouveaux panneaux disponibles. Lis les tooltips avant toute dépense irréversible.","optional":false,"tag":"DÉCOUVERTE","check":["Spelunking accessible","Research repéré","Magasin contrôlé"]},{"id":"w7-one-currency","phase":"RÈGLE W7","title":"Travaille une seule monnaie W7 à la fois","action":"Dans chaque interface, choisis le prochain déblocage qui ouvre un système ou un multiplicateur global, note son coût, puis affecte tes claims et upgrades uniquement à cette cible. Termine-la avant de passer à Minehead, Sushi, Research ou The Button suivant.","optional":false,"tag":"ANTI-DISPERSION","check":["Un seul système choisi","Prochain coût noté","Production affectée","Autres dépenses suspendues"]},{"id":"w7-claim-plan","phase":"ROUTINE W7","title":"Aligne les claims sur ton absence","action":"Pour Spelunking, Minehead et Sushi, lis le temps avant cap, compare-le à ta prochaine absence et investis en capacité uniquement si nécessaire. Sinon, choisis vitesse, profondeur ou tier.","optional":false,"tag":"CAPACITÉ","check":["Trois temps avant cap lus","Durée AFK estimée","Un seul cap corrigé"]},{"id":"spelunk-first","phase":"SPELUNKING","title":"Lance la première expédition","action":"Choisis la première cave, affecte l’équipe/équipement disponible et démarre immédiatement. Note l’heure de retour afin de ne pas laisser l’expédition terminée sans claim.","optional":false,"tag":"INSTALLATION","check":["Première expédition lancée","Heure de claim connue"]},{"id":"spelunk-claim","phase":"SPELUNKING","title":"Claim puis relance sans temps mort","action":"A chaque retour, récupère les trouvailles, équipe les améliorations utiles et relance une cave. Une équipe au repos ne gagne ni profondeur ni ressources.","optional":false,"tag":"ROUTINE","check":["Récompenses réclamées","Nouvelle expédition active"]},{"id":"spelunk-depth","phase":"SPELUNKING","title":"Augmente la profondeur avant de farmer confortablement","action":"Choisis les upgrades qui ouvrent profondeur, vitesse, capacité et qualité. Ne reste pas sur une cave facile si la suivante est atteignable avec un petit changement d’équipement.","optional":false,"tag":"PRIORITÉ","check":["Profondeur suivante ciblée","Upgrade structurant acheté"]},{"id":"spelunk-loadout","phase":"SPELUNKING","title":"Equipe les trouvailles selon l’objectif","action":"Utilise vitesse/profondeur pour progresser et quantité/qualité lors du farm. Remplace les objets faibles, mais garde une pièce situationnelle si elle débloque une cave.","optional":false,"tag":"ÉQUIPEMENT","check":["Chaque emplacement équipé","Loadout progression ou farm défini"]},{"id":"spelunk-cap","phase":"SPELUNKING","title":"Adapte la durée à tes connexions","action":"Choisis une cave et une durée qui ne terminent pas plusieurs heures avant ton retour. Améliore la capacité si les récompenses sont souvent perdues au cap.","optional":false,"tag":"AFK","check":["Durée adaptée","Capacité suffisante"]},{"id":"w7-map-start","phase":"PUSH MAP PAR MAP","title":"Ouvre les premières monster maps","action":"Utilise ta meilleure Master Class avec Brightside, 100 % précision et meilleur clear. Sur chaque map, ramasse les nouveaux drops avant de passer à la suivante.","optional":false,"tag":"MAPS","check":["Premières maps ouvertes","Nouveaux drops enregistrés au Slab"]},{"id":"w7-map-bonus","phase":"MASTER CLASSES","title":"Active les bonus de map des Forms","action":"Lis les objectifs Wraith, Tempest et Arcanist liés aux maps. Place la bonne Master Class sur la cible et valide ses gains avant de la déplacer.","optional":false,"tag":"FORMS","character":"Death Bringer, Wind Walker, Arcane Cultist","check":["Objectifs de map inspectés","Form adaptée utilisée"]},{"id":"research-open","phase":"RESEARCH","title":"Débloque la Research Grid","action":"Termine la quête ou condition W7 qui ouvre Research, puis inspecte la grid sans dépenser au hasard. Identifie les cases EXP, vitesse et capacité.","optional":false,"tag":"INSTALLATION","check":["Research accessible","Grid inspectée","Première observation placée"]},{"id":"research-speed","phase":"RESEARCH","title":"Priorise EXP et vitesse de Research","action":"Investis d’abord dans les améliorations qui accélèrent tous les futurs paliers. Prends un bonus de dégâts seulement s’il retire immédiatement un mur de progression.","optional":false,"tag":"PRIORITÉ","check":["EXP améliorée","Vitesse améliorée","Prochain palier identifié"]},{"id":"research-layout","phase":"RESEARCH","title":"Optimise les adjacences de la Grid","action":"Déplace les observations pour profiter des connexions et multiplicateurs visibles. Compare le résultat affiché avant et après, puis conserve la meilleure disposition.","optional":false,"tag":"GRID","check":["Adjacences contrôlées","Disposition comparée","Meilleur rendement conservé"]},{"id":"research-next-cell","phase":"RESEARCH","title":"Prépare une seule case de Grid","action":"Choisis la case qui ouvre le prochain système ou multiplicateur, note ses observations et son coût, puis organise la grid pour cette cible. Ne disperse pas les ressources sur plusieurs branches.","optional":false,"tag":"FARM CIBLÉ","check":["Case choisie","Prérequis notés","Grid orientée","Case obtenue"]},{"id":"observation-list","phase":"OBSERVATIONS","title":"Dresse la liste des observations manquantes","action":"Ouvre l’interface Research et note chaque map/condition indiquée. Classe-les par monde pour faire un seul circuit de collecte.","optional":false,"tag":"ORGANISATION","check":["Liste des observations créée","Circuit W1–W7 préparé"]},{"id":"observation-old","phase":"OBSERVATIONS","title":"Collecte les observations des anciens mondes","action":"Téléporte le personnage requis sur chaque ancienne map signalée et réalise la condition affichée. Vérifie l’enregistrement avant de repartir.","optional":false,"tag":"RETOUR","check":["Observations W1–W3 contrôlées","Observations W4–W6 contrôlées"]},{"id":"observation-w7","phase":"OBSERVATIONS","title":"Collecte les observations W7","action":"Progresse jusqu’aux maps demandées, dont l’observation tardive du sommet lorsque disponible. Ne suppose pas qu’une présence sur la map suffit : lis la condition.","optional":false,"tag":"W7","check":["Observations des maps ouvertes récupérées","Observation tardive notée"]},{"id":"minehead-open","phase":"MINEHEAD","title":"Débloque Minehead","action":"Progresse dans W7/Murky Trenches jusqu’au système Minehead et termine son introduction. Réclame la première ressource avant de quitter l’interface.","optional":false,"tag":"SYSTÈME 2026","check":["Minehead accessible","Première production lancée"]},{"id":"minehead-upgrade","phase":"MINEHEAD","title":"Monte production, capacité puis accès","action":"Dépense dans la vitesse/production et la capacité adaptée à ton AFK, puis dans les branches ouvrant le contenu suivant. Compare toujours le temps réel avant cap.","optional":false,"tag":"PRIORITÉ","check":["Production améliorée","Capacité adaptée","Prochaine branche ciblée"]},{"id":"minehead-next-cost","phase":"MINEHEAD","title":"Économise pour le prochain palier Minehead","action":"Compare profondeur, production et capacité, sélectionne celle qui débloque le meilleur palier, puis garde la monnaie jusqu’au coût exact. Claim avant saturation sans acheter les petits niveaux intermédiaires inutiles.","optional":false,"tag":"FARM CIBLÉ","check":["Palier choisi","Coût noté","Monnaie réservée","Palier acheté"]},{"id":"minehead-claim","phase":"MINEHEAD","title":"Claim Minehead avant saturation","action":"Ajoute Minehead à la routine W7. Dépense ou convertis les ressources après le claim afin que la production suivante reste utile.","optional":false,"tag":"ROUTINE","check":["Capacité non pleine","Ressources dépensées"]},{"id":"sushi-open","phase":"SUSHI STATION","title":"Débloque Sushi Station","action":"Atteins la zone/condition indiquée en jeu puis lance la première production. Vérifie le tier actuel avant toute fusion.","optional":false,"tag":"SYSTÈME 2026","check":["Sushi Station accessible","Premier sushi produit"]},{"id":"sushi-combine","phase":"SUSHI STATION","title":"Combine uniquement jusqu’au palier sûr affiché","action":"Fais les combinaisons progressivement et arrête-toi si le tooltip ou les patch notes en jeu signalent un cap. Ne suis pas une ancienne capture indiquant Tier 59 sans vérifier la version actuelle.","optional":false,"tag":"ANTI-VIEUX GUIDE","check":["Tier actuel contrôlé en jeu","Aucune combinaison au-delà du cap affiché"]},{"id":"sushi-next-tier","phase":"SUSHI STATION","title":"Vise un seul nouveau tier","action":"Repère la combinaison exacte du prochain Sushi Tier, réserve les sushis nécessaires et améliore seulement fuel, slots ou vitesse si cela réduit directement ce temps. Combine puis vérifie le bonus global obtenu.","optional":false,"tag":"FARM CIBLÉ","check":["Tier cible choisi","Combinaison préparée","Upgrade justifié","Bonus global vérifié"]},{"id":"sushi-routine","phase":"SUSHI STATION","title":"Intègre Sushi Station à la boucle W7","action":"Claim, combine au palier prévu, dépense les récompenses puis relance. Ne garde pas une station pleine entre deux longues absences.","optional":false,"tag":"ROUTINE","check":["Station réclamée","Production relancée"]},{"id":"button-open","phase":"THE BUTTON","title":"Débloque The Button","action":"Termine la condition affichée par W7 et ouvre le système. Utilise uniquement tes statistiques actuelles : l’ancien snapshotting a été corrigé.","optional":false,"tag":"SYSTÈME 2026","check":["The Button accessible","Valeurs actuelles utilisées"]},{"id":"button-upgrade","phase":"THE BUTTON","title":"Améliore sans snapshot","action":"Choisis les upgrades permanents selon le goulot du compte et vérifie l’effet après achat. Ignore tout guide demandant d’équiper temporairement un ancien snapshot.","optional":false,"tag":"ANTI-VIEUX GUIDE","check":["Upgrade acheté","Effet vérifié","Aucun snapshot utilisé"]},{"id":"button-after-check","phase":"THE BUTTON","title":"Mesure le bonus après chaque achat","action":"Note la statistique concernée avant l’achat, dépense sur un seul upgrade permanent puis contrôle la nouvelle valeur. Si le gain est faible, change de branche au prochain cycle plutôt que d’insister.","optional":false,"tag":"VALIDATION","check":["Valeur avant notée","Un upgrade acheté","Valeur après comparée"]},{"id":"coral-drop","phase":"CORAL CAVE","title":"Farm le drop d’accès à Coral Cave","action":"Sur la map W7 indiquée par le jeu, utilise la classe de drop adaptée et reste jusqu’à obtenir l’objet d’ouverture. Enregistre aussi les drops au Slab.","optional":false,"tag":"DÉBLOCAGE","check":["Objet d’accès obtenu","Objet enregistré","Quête rapportée"]},{"id":"coral-open2","phase":"CORAL CAVE","title":"Ouvre et inspecte Coral Cave","action":"Entre dans la cave, parle aux NPC et repère les upgrades liés au Tome/anciens systèmes. Priorise les bonus permanents avant les dépenses cosmétiques.","optional":false,"tag":"SYSTÈME","check":["Coral Cave accessible","Upgrades inspectés"]},{"id":"trench-enter","phase":"MURKY TRENCHES","title":"Ouvre Murky Trenches","action":"Progresse sur les branches W7 jusqu’à la nouvelle zone. Visite chaque map secondaire et parle aux NPC avant de choisir un long farm.","optional":false,"tag":"MISE À JOUR 2026","check":["Murky Trenches accessible","Maps secondaires visitées"]},{"id":"depth-charge","phase":"MURKY TRENCHES","title":"Débloque Depth Charge chez Minehead","action":"Atteins la map correspondante, lis les règles du mini-jeu et effectue les tentatives gratuites/renouvelables disponibles sans achat payant.","optional":false,"tag":"MINI-JEU","check":["Depth Charge accessible","Première tentative effectuée","Récompense réclamée"]},{"id":"swap-meet","phase":"MURKY TRENCHES","title":"Visite Glimbo’s Swap Meet","action":"Ouvre le Swap Meet, compare les échanges et n’achète que ce qui débloque un multiplicateur ou une progression difficile à obtenir autrement.","optional":false,"tag":"BOUTIQUE","check":["Swap Meet accessible","Offres contrôlées","Achat prioritaire effectué ou reporté"]},{"id":"green-water","phase":"GREEN WATER","title":"Atteins Crystal Glunko Cove et ouvre Green Water","action":"Progresse The Hole jusqu’à la cavern correspondante puis complète la condition exacte affichée en jeu. Les coûts W7 tardifs doivent toujours être confirmés dans le tooltip actuel.","optional":false,"tag":"DÉBLOCAGE 2026","check":["Crystal Glunko Cove accessible","Condition Green Water validée","Green Water actif"]},{"id":"green-water-target","phase":"GREEN WATER","title":"Réserve chaque couleur pour un upgrade","action":"Choisis un upgrade global, note la couleur et le coût, puis bloque cette eau jusqu’à l’achat. Ne répartis pas les trois couleurs entre des bonus mineurs tant qu’un déblocage majeur est proche.","optional":false,"tag":"FARM CIBLÉ","check":["Upgrade choisi","Couleur identifiée","Coût réservé","Achat validé"]},{"id":"char11","phase":"ROSTER","title":"Débloque et crée le 11e personnage","action":"Atteins le Family Level requis affiché, crée le slot 11 et active immédiatement Anvil, traps, skull, Divinity/Lab et les systèmes passifs de ce personnage.","optional":false,"tag":"PERSONNAGE","character":"Personnage 11 — classe selon le goulot actuel","check":["Personnage 11 créé","Anvil active","Trap posé","Skull équipé","Rôle défini"]},{"id":"dreadnaught","phase":"ROSTER","title":"Ouvre Dreadnaught Chamber","action":"Lorsque la condition est atteinte, place les 11 personnages à Pirate Mess Hall comme demandé puis entre dans la nouvelle map. Replace ensuite chacun sur son objectif.","optional":false,"tag":"MAP 11 PERSONNAGES","check":["11 personnages présents pour la condition","Dreadnaught Chamber ouverte","Roster réaffecté après ouverture"]},{"id":"w7-daily-loop","phase":"ROUTINE","title":"Exécute la boucle W7 dans le même ordre","action":"Claim Spelunking, Research, Minehead, Sushi Station et The Button ; vérifie ensuite Forms/maps, Coral/Trenches puis retourne aux anciens systèmes.","optional":false,"tag":"QUOTIDIEN","check":["Spelunking","Research","Minehead","Sushi","Button","Forms contrôlées"]},{"id":"w7-patch-check","phase":"VIGILANCE","title":"Contrôle les tooltips après chaque patch","action":"Conserve l’ordre stratégique du guide, mais remplace immédiatement tout coût, tier ou cap qui diffère dans le jeu. Les valeurs W7 sont plus volatiles que les mondes précédents.","optional":false,"tag":"IMPORTANT","check":["Version/patch actuel lu","Valeurs sensibles confirmées en jeu"]}]},{"slug":"endgame","number":"∞","name":"Endgame","subtitle":"Boucles et caps modernes","accent":"#f0cf68","goal":"Transformer tous les systèmes en multiplicateurs qui s’alimentent entre eux.","gate":["Lab 75 + Divinity 40 tous persos","Samples proches de 90 %","Rift 61+","Routine quotidienne < 15 min"],"steps":[{"id":"end-roster-audit","phase":"AUDIT INITIAL","title":"Attribue un rôle permanent à chaque personnage","action":"Pour chacun des 11 personnages, note combat actif, métier principal, sample, Lab/Divinity et Form éventuelle. Aucun personnage ne doit rester sur une map par défaut sans objectif.","optional":false,"tag":"ROSTER","check":["11 rôles combat définis","11 rôles métier définis","11 samples planifiés"]},{"id":"end-roster-meta","phase":"ROSTER","title":"Vérifie les doublons avant tout changement","action":"Conserve une branche de chaque Elite/Master et un seul Voidwalker. Les doublons servent un goulot précis ; ne change pas une classe uniquement parce qu’une ancienne tier list le disait.","optional":false,"tag":"CHOIX DURABLE","check":["Six branches couvertes","Trois Master Classes couvertes","Un seul Voidwalker","Chaque doublon justifié"]},{"id":"end-presets","phase":"ROSTER","title":"Nettoie les presets de tous les personnages","action":"Preset 1 combat, preset 2 métier ou système. Retire les talents hybrides, vérifie cartes, star signs, prayers, divinity link, obols, chips, foods et barre d’attaques.","optional":false,"tag":"CONFIGURATION","character":"Tout le roster","check":["Talents","Cards","Star Signs","Prayers","God link","Obols","Chips","Food","Attack bar"]},{"id":"end-alch-daily","phase":"ALCHEMY","title":"Dépense les liquids avant le cap","action":"Chaque jour, dépense liquids en bubbles, vials ou upgrades utiles. Ne laisse pas les cauldrons pleins pendant que tu attends un coût lointain.","optional":false,"tag":"QUOTIDIEN","check":["Liquids dépensés","Cauldrons non capés"]},{"id":"end-alch-boron","phase":"ALCHEMY","title":"Utilise Boron sur les bubbles éligibles","action":"Prépare les bubbles au seuil requis, sélectionne celles avec le meilleur impact global et utilise les upgrades atomiques quotidiens sans oubli.","optional":false,"tag":"ATOMS","check":["Boron utilisé","Bubble prioritaire sélectionnée"]},{"id":"end-alch-colors","phase":"ALCHEMY","title":"Monte les multiplicateurs de couleur","action":"Compare Orange, Green, Purple et Yellow : travaille la couleur dont le total limite les bubbles importantes, sans abandonner Speed/Luck des autres.","optional":false,"tag":"CAULDRONS","check":["Couleur faible identifiée","Boosts Speed/Luck dépensés"]},{"id":"end-alch-key","phase":"ALCHEMY","title":"Contrôle les bubbles structurantes","action":"Vérifie Shaquracy, FMJ, Diamond Chef, les bubbles de sampling, multi-resource, main stat et dégâts. Monte d’abord celle qui retire le goulot mesuré.","optional":false,"tag":"CHECKLIST","check":["Shaquracy","FMJ","Diamond Chef","Sampling","Multi-resource","Main stats"]},{"id":"end-vials","phase":"ALCHEMY","title":"Pousse les vials rentables puis les niveaux verts","action":"Découvre tous les vials accessibles, monte les coûts faciles et vise les paliers verts qui alimentent les multiplicateurs associés. Evite de vider un matériau time-gated pour un gain minuscule.","optional":false,"tag":"VIALS","check":["Tentatives quotidiennes faites","Vials faciles verts","Coûts time-gated protégés"]},{"id":"end-sample-plan","phase":"3D PRINTER","title":"Prépare un re-sample complet","action":"Ne re-sample pas un seul personnage au hasard. Attends un bond d’efficacité, puis prépare outils, talents, cards, food, star signs, prayers, chips, obols et God links pour tout le roster.","optional":false,"tag":"PRÉPARATION","check":["Checklist équipement prête","Anciennes valeurs notées","Session de re-sample planifiée"]},{"id":"end-sample-rate","phase":"3D PRINTER","title":"Approche le cap de Sample Rate","action":"Equipe Printer Sampling et tous les multiplicateurs disponibles jusqu’à approcher 90 %. Vérifie la valeur affichée avant chaque capture.","optional":false,"tag":"CAP","stats":["Sample Rate : proche de 90 %"],"check":["Taux contrôlé sur chaque sampler"]},{"id":"end-sample-ore","phase":"3D PRINTER","title":"Re-sample les ores et logs de base","action":"Sur DK/Squire et ES/Wizard, capture les ressources alimentant Refinery, Atoms et Alchemy. Compare le nouveau sample à l’ancien avant de l’écraser.","optional":false,"tag":"SESSION","check":["Ore sample amélioré","Log sample amélioré","Fuels sécurisés"]},{"id":"end-sample-other","phase":"3D PRINTER","title":"Re-sample poissons, insectes et critters","action":"Utilise les spécialistes et presets exacts. Affecte ensuite chaque slot aux matériaux réellement consommés, pas à la valeur la plus impressionnante.","optional":false,"tag":"SESSION","check":["Fish sample","Bug sample","Critter production planifiée"]},{"id":"end-printer-layout","phase":"3D PRINTER","title":"Répartis les slots par priorité","action":"Ordre conseillé : fuels Refinery, matériaux atomiques/bubbles, time-gates de craft, puis besoins temporaires. Contrôle les slots après chaque gros achat.","optional":false,"tag":"LAYOUT","check":["Fuels couverts","Atoms/bubbles couverts","Aucun slot inutile"]},{"id":"end-salt-chart","phase":"REFINERY","title":"Maintiens une pyramide de sels positive","action":"Calcule la consommation de chaque couche et garde les sels inférieurs capables d’alimenter les supérieurs. Désactive une couche avant qu’elle ne vide durablement sa base.","optional":false,"tag":"TIME-GATE","check":["Red positif","Green positif","Couches hautes soutenables"]},{"id":"end-salt-rank","phase":"REFINERY","title":"Rank-up uniquement avec fuel soutenable","action":"Avant un rank, vérifie le coût par cycle et le stock imprimé. Ne rank pas automatiquement si le nouveau débit casse toute la pyramide.","optional":false,"tag":"VALIDATION","check":["Nouveau coût lu","Fuel Time positif après projection"]},{"id":"end-construction","phase":"CONSTRUCTION","title":"Pousse niveaux de bâtiments et Construct Mastery","action":"Garde les meilleurs constructeurs en Player EXP, améliore les bâtiments/towers structurants puis totalise les niveaux pour les bonus de mastery.","optional":false,"tag":"LONG TERME","check":["Cog board optimisé","Bâtiment prioritaire actif","Mastery suivant identifié"]},{"id":"end-library","phase":"TALENT LIBRARY","title":"Ne laisse jamais les checkouts caper","action":"Réclame les livres, remplace les rolls faibles et booke respawn, talents account-wide, efficacité, Cranium et Forms avant les talents marginaux.","optional":false,"tag":"ROUTINE","check":["Checkout réclamé","Talent prioritaire amélioré"]},{"id":"end-rift-chain","phase":"RIFT","title":"Termine les objectifs Rift dans l’ordre","action":"Prépare la classe adaptée à chaque objectif, vérifie les conditions avant la run et repars améliorer le compte si le clear devient déraisonnablement long.","optional":false,"tag":"PROGRESSION","check":["Objectif actuel lu","Classe adaptée","Prochain unlock noté"]},{"id":"end-rift61","phase":"RIFT","title":"Atteins Rift 61 et active Cooking Mastery","action":"Pousse jusqu’au palier requis puis ouvre Cooking Mastery. Vérifie son interface avant d’investir massivement les ladles ou ribbons.","optional":false,"tag":"OBJECTIF","check":["Rift 61 atteint","Cooking Mastery accessible"]},{"id":"end-skill-mastery","phase":"RIFT","title":"Monte les Skill Masteries par paliers","action":"Fais gagner des niveaux de skills à tout le roster, pas uniquement aux spécialistes. Vise le prochain bonus collectif atteignable avec les métiers les plus bas.","optional":false,"tag":"ACCOUNT-WIDE","character":"Tout le roster","check":["Skills faibles identifiés","Prochain palier mastery ciblé"]},{"id":"end-cook-speed","phase":"COOKING","title":"Travaille d’abord la vitesse exponentielle","action":"Monte Diamond Chef, kitchens, meals de vitesse, Fluoride, ribbons et bonus Hole/Rift avant de forcer une recette aux temps absurdes.","optional":false,"tag":"PRIORITÉ","check":["Diamond Chef contrôlé","Kitchen speed améliorée","Meal de vitesse ciblé"]},{"id":"end-cook-meals","phase":"COOKING","title":"Monte tous les meals bon marché avant le mur","action":"Trie par temps du prochain niveau et achète les gains rapides. Reviens aux meals lents après un nouveau multiplicateur de vitesse.","optional":false,"tag":"ROUTINE","check":["Meals rapides montés","Meal lent reporté avec raison"]},{"id":"end-cook-mastery","phase":"COOKING","title":"Alterne niveaux normaux et Mastery","action":"Compare le multiplicateur apporté par chaque côté. Investis là où le temps par gain est le meilleur plutôt que de maxer une colonne par habitude.","optional":false,"tag":"MASTERY","check":["Temps comparés","Meilleur palier choisi"]},{"id":"end-hole-daily","phase":"THE HOLE","title":"Dépense toutes les ressources quotidiennes utiles","action":"Lanternes, villagers, schematics, Measurement et caverns doivent être contrôlés dans une seule boucle. Ne laisse pas une capacité pleine.","optional":false,"tag":"QUOTIDIEN","check":["Lanternes","Villagers","Schematics","Measurement","Caverns"]},{"id":"end-caverns","phase":"THE HOLE","title":"Ouvre les Sentinel Caverns tardives","action":"Progresse jusqu’à Fountain, Bottomless Trench et Crystal Glunko Cove selon les conditions affichées. Répartis les lanternes lorsque plusieurs unlocks se soutiennent.","optional":false,"tag":"PROGRESSION","check":["Cavern suivante ciblée","Condition vérifiée en jeu"]},{"id":"end-equinox","phase":"EQUINOX","title":"Travaille un Nightmare Challenge à la fois","action":"Après le prérequis Research, choisis un challenge réalisable, prépare le roster puis valide-le avant de redistribuer les ressources.","optional":false,"tag":"CHALLENGES","check":["Challenge choisi","Prérequis satisfait","Récompense investie"]},{"id":"end-research","phase":"RESEARCH","title":"Complète Grid, observations et paliers","action":"Réorganise la grid après chaque nouvelle observation, monte les upgrades de vitesse/EXP et prépare les seuils nécessaires à Equinox/anciens systèmes.","optional":false,"tag":"W7","check":["Grid optimisée","Observations contrôlées","Prochain seuil noté"]},{"id":"end-greenstack","phase":"COLLECTION","title":"Perma-greenstack les ressources accessibles","action":"Monte chaque pile à 10M une fois, vérifie son enregistrement puis autorise son utilisation. Commence par les monstres et productions faciles.","optional":false,"tag":"10 MILLIONS","check":["Liste des manquants ouverte","Pile à 10M vérifiée","Ressource suivante choisie"]},{"id":"end-slab","phase":"COLLECTION","title":"Complète le Slab par familles","action":"Traite shops, crafts, quest items, équipements et drops monde par monde. Obtiens chaque objet réellement avant de le vendre ou recycler.","optional":false,"tag":"SLAB","check":["Famille actuelle contrôlée","Objets faciles enregistrés"]},{"id":"end-statues","phase":"STATUES","title":"Onyx puis Zenith les statues prioritaires","action":"Farm avec la classe adaptée, termine la condition Onyx et investis dans les statues qui servent tous les builds. Vérifie les prérequis Zenith actuels en jeu.","optional":false,"tag":"COLLECTION","check":["Statue cible choisie","Onyx obtenu ou progression mesurée","Zenith vérifié"]},{"id":"end-cards","phase":"CARDS","title":"Farm les cards avec la bonne classe","action":"ES pour drops normaux/cartes, DK pour Rare Drop Bags et SB selon l’objectif. Equipe le set de cards/drop avant le farm et contrôle les étoiles obtenues.","optional":false,"tag":"FARM","check":["Classe adaptée","Card set équipé","Palier cible défini"]},{"id":"end-stamps","phase":"STAMPS","title":"Pousse les stamps à chaque ordre de grandeur de monnaie","action":"Filtre combat, skills et utility ; achète les niveaux peu coûteux puis utilise les réductions/capacités avant les stamps chers.","optional":false,"tag":"ACCOUNT-WIDE","check":["Stamps bon marché montés","Capacité matière contrôlée","Prochain coût préparé"]},{"id":"end-obols","phase":"OBOLS","title":"Nettoie les family et personal obols","action":"Equipe drop/dégâts sur les farmers actifs et efficiency sur les samplers. Fusionne/verrouille avec prudence et ne détruis pas un set métier rare.","optional":false,"tag":"ÉQUIPEMENT","check":["Family board rempli","Personal boards remplis","Sets métiers protégés"]},{"id":"end-daily","phase":"ROUTINE","title":"Réduis la routine quotidienne à une boucle fixe","action":"Alchemy, shops, Anvil, Forge, Refinery, Library, W4 skills, W5 skills/Hole, W6 skills et W7 systems dans le même ordre. Supprime les checks sans bénéfice mesurable.","optional":false,"tag":"< 15 MIN","check":["W1–W3","W4","W5/Hole","W6","W7","Personnages replacés"]},{"id":"end-weekly","phase":"ROUTINE","title":"Exécute la checklist hebdomadaire","action":"Happy Hour, Kilroy, chip/jewel rotation, weekly boss, Equinox, companions/free claims et événements actifs. Programme les coûts avant le reset.","optional":false,"tag":"HEBDOMADAIRE","check":["Happy Hour","Kilroy","Chips/Jewels","Weekly Boss","Equinox","Event actuel"]},{"id":"end-weekly-budget","phase":"ROUTINE","title":"Prépare les coûts hebdomadaires avant le reset","action":"Pour chips/jewels, boss, Equinox et achats limités, note les coûts encore manquants puis affecte un seul farmer ou slot Printer à chaque ressource. Termine les coûts les plus proches du reset en premier.","optional":false,"tag":"PLANIFICATION","check":["Coûts listés","Échéances classées","Farmers affectés","Achats effectués"]},{"id":"end-bottleneck","phase":"AUDIT","title":"Travaille le plus petit multiplicateur vérifié","action":"Chaque semaine, compare précision, dégâts, drop rate, samples, meals, bubbles, artifacts, crops, Research et Forms. Choisis le système le plus en retard avec un gain mesurable.","optional":false,"tag":"RÈGLE FINALE","check":["Mesures comparées","Un seul goulot choisi","Résultat recontrôlé après amélioration"]},{"id":"end-result-log","phase":"AUDIT","title":"Mesure le résultat avant de changer de système","action":"Après chaque session d’amélioration, relève la nouvelle valeur du goulot, compare-la à l’ancienne et note le prochain seuil. Ne passe à un autre système que si le gain prévu y est désormais supérieur.","optional":false,"tag":"VALIDATION FINALE","check":["Valeur avant/après comparée","Gain confirmé","Prochain goulot choisi"]},{"id":"equinox","phase":"EQUINOX","title":"Fais les Nightmare Challenges","action":"Après Research G8, complète les 41 nouveaux Dream Challenges et investis dans Nonstop Studies.","why":"Ajout majeur d’avril 2026.","optional":false},{"id":"worship","phase":"WORSHIP","title":"Pousse les TD modernes","action":"Sauvegarde tes meilleures runs, combine Kraken/Poisonic/Party Starter/Stormcaller/Frozone/Voidinator et améliore les towers Construction.","why":"La stratégie de contrôle dépasse les dégâts bruts tardifs.","optional":false}]}];
const TOTAL=WORLDS.reduce((n,w)=>n+w.steps.length,0);let mode="guided",query="";
const esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const load=()=>{try{return JSON.parse(localStorage.getItem("idleon-guide-progress")||"{}")||{}}catch{return{}}};
const save=d=>localStorage.setItem("idleon-guide-progress",JSON.stringify(d));
const current=()=>{const slug=location.hash.slice(1);return WORLDS.find(w=>w.slug===slug)};
function header(done,w){const g=Object.values(done).filter(Boolean).length;return '<header><a class="brand" href="index.html"><b>I</b><span>IDLEON<br><strong>ROUTE</strong></span></a><a class="metaLink" href="builds.html">BUILDS META</a><nav>'+WORLDS.map(x=>'<a class="'+(w&&x.slug===w.slug?'active':'')+'" style="--a:'+x.accent+'" href="#'+x.slug+'">'+x.number+'</a>').join('')+'</nav><div class="global"><span>GLOBAL</span><strong>'+Math.round(g/TOTAL*100)+'%</strong><i><em style="width:'+g/TOTAL*100+'%"></em></i></div></header>'}
function home(done){return header(done)+'<main><section class="hero"><div class="eyebrow">GUIDE FRANÇAIS · AOÛT 2026</div><h1>Ta route complète<br>vers <em>l’endgame.</em></h1><p>Un plan concret, monde par monde. Chaque système important et chaque objectif — dans le bon ordre.</p><a class="start" href="#w1">COMMENCER AU MONDE 1 →</a><div class="rule"><b>LA RÈGLE D’OR</b> Push → nouveau monde → multiplicateurs → optimisation.</div></section><section class="road"><small>LA ROADMAP</small><h2>Choisis ton monde</h2><div class="grid">'+WORLDS.map((w,i)=>{const c=w.steps.filter(s=>done[w.slug+'-'+s.id]).length;return '<a class="card" style="--a:'+w.accent+'" href="#'+w.slug+'"><span>'+w.number+'</span><small>'+(i===7?'APRÈS LES MONDES':'MONDE '+(i+1))+'</small><h3>'+esc(w.name)+'</h3><p>'+esc(w.subtitle)+'</p><i><em style="width:'+c/w.steps.length*100+'%"></em></i><b>'+c+'/'+w.steps.length+' ÉTAPES</b></a>'}).join('')+'</div></section></main>'}
function guide(done,w){const completed=w.steps.filter(s=>done[w.slug+'-'+s.id]).length;let filtered=w.steps.filter(s=>(s.title+' '+s.action+' '+s.phase+' '+(s.character||'')+' '+(s.talents||[]).join(' ')+' '+(s.stats||[]).join(' ')).toLowerCase().includes(query.toLowerCase())&&(mode==='all'||mode==='todo'&&!done[w.slug+'-'+s.id]||mode==='optional'&&s.optional||mode==='guided'&&!s.optional&&!done[w.slug+'-'+s.id]));if(mode==='guided')filtered=filtered.slice(0,1);const phases=[...new Set(filtered.map(s=>s.phase))];const cards=s=>[["TALENTS — ORDRE",s.talents],["STATS À VISER",s.stats],["MÉTIER / PALIER",s.skills],["ÉQUIPEMENT",s.gear],["AVANT DE COCHER",s.check]].filter(x=>x[1]).map(x=>'<section class="detail"><b>'+x[0]+'</b><ul>'+x[1].map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul></section>').join('');return header(done,w)+'<main style="--world:'+w.accent+'"><section class="guideHero"><a href="#">← TOUS LES MONDES</a><small>MONDE '+w.number+'</small><h1>'+esc(w.name)+'</h1><p>'+esc(w.goal)+'</p><div class="bar"><i><em style="width:'+completed/w.steps.length*100+'%"></em></i><b>'+completed+' / '+w.steps.length+' étapes terminées</b></div><div class="gates">'+w.gate.map(g=>'<span>✓ '+esc(g)+'</span>').join('')+'</div></section><section class="content"><div class="filters"><input id="search" value="'+esc(query)+'" placeholder="Rechercher une étape…"><button data-mode="guided">GUIDÉ</button><button data-mode="all">TOUT</button><button data-mode="todo">À FAIRE</button><button data-mode="optional">OPTIONNEL</button></div>'+(mode==='guided'?'<div class="guided"><b>'+(filtered.length?'OBJECTIF ACTUEL':'MONDE TERMINÉ')+'</b><span>'+(filtered.length?'Fais uniquement cette étape. La suivante apparaîtra après validation.':'Toutes les étapes obligatoires sont cochées.')+'</span></div>':'')+phases.map(p=>'<section class="phase"><h2>'+esc(p)+'</h2>'+filtered.filter(s=>s.phase===p).map(s=>{const key=w.slug+'-'+s.id,d=!!done[key];return '<article class="step '+(d?'done':'')+'"><button class="check" data-key="'+key+'">'+(d?'✓':'')+'</button><div><small>ÉTAPE '+String(w.steps.indexOf(s)+1).padStart(2,'0')+(s.quest?' · QUÊTE '+s.quest:s.optional?' · OPTIONNEL':'')+'</small><h3>'+esc(s.title)+'</h3>'+(s.character?'<div class="character">PERSONNAGE : <b>'+esc(s.character)+'</b></div>':'')+'<p>'+esc(s.action)+'</p><div class="details">'+cards(s)+'</div>'+(s.why?'<aside><b>POURQUOI</b> '+esc(s.why)+'</aside>':'')+'</div></article>'}).join('')+'</section>').join('')+'</section></main>'}
function render(options={}){const done=load(),w=current(),y=options.keepScroll?window.scrollY:null,focus=options.keepFocus;document.getElementById('app').innerHTML=w?guide(done,w):home(done);document.querySelectorAll('.check').forEach(b=>b.onclick=()=>{done[b.dataset.key]=!done[b.dataset.key];save(done);render({keepScroll:true})});document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('sel',b.dataset.mode===mode);b.onclick=()=>{mode=b.dataset.mode;render({keepScroll:true})}});const s=document.getElementById('search');if(s){s.oninput=e=>{query=e.target.value;render({keepScroll:true,keepFocus:true})};if(focus){s.focus({preventScroll:true});s.setSelectionRange(query.length,query.length)}}if(y!==null)requestAnimationFrame(()=>scrollTo(0,y))}
addEventListener('hashchange',()=>{mode='guided';query='';render()});render();
